const clamp=(x,a=0,b=100)=>Math.max(a,Math.min(b,x));const rand=(a,b)=>a+Math.random()*(b-a);const int=(a,b)=>Math.floor(rand(a,b+1));const pick=a=>a[Math.floor(Math.random()*a.length)];
const fmt=n=>new Intl.NumberFormat('es-ES').format(Math.round(n));const money=n=>fmt(n)+' €';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
