let S=null,activeTab='hub',tableMode='full',noticeTimer=null;
function notify(t){const old=$('notice');if(old)old.remove();const el=document.createElement('div');el.id='notice';el.className='notice';el.textContent=t;document.body.appendChild(el);clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>el.remove(),3500)}
function persist(){if(!S)return;try{store.setItem(SAVE_KEY,JSON.stringify(S));}catch(e){}}
function mutate(stats){for(let [k,v] of Object.entries(stats)){if(k==='money')S.player.balance+=v;else if(k==='wage')S.player.wage+=v;else if(k==='injuryChance'){if(Math.random()<v){S.player.injured=int(1,3);note('Parte médico: molestias musculares. Baja estimada: '+S.player.injured+' partidos.');}}else if(k in S.player){S.player[k]=clamp(S.player[k]+v,k==='fitness'||k==='morale'||k==='focus'||k==='trust'||k==='chemistry'||k==='rep'?0:-999,k==='rep'?100:k==='wage'?500000:100)}}
}
function note(t){S.inbox.unshift({round:S.round+1,text:t});S.inbox=S.inbox.slice(0,25)}
function newTable(names){return Object.fromEntries(names.map(n=>[n,{p:0,w:0,d:0,l:0,gf:0,ga:0,pts:0,form:[]}]))}
function buildSchedule(names){let a=[...names],n=a.length,first=[];if(S?.year===2026&&S.club.tier===2&&a.includes('CE Sabadell')&&a.includes('Sporting de Gijón')){a=a.filter(x=>x!=='CE Sabadell'&&x!=='Sporting de Gijón');a.unshift('Sporting de Gijón');a.push('CE Sabadell')}for(let r=0;r<n-1;r++){let games=[];for(let i=0;i<n/2;i++){let h=a[i],away=a[n-1-i];if(r%2===0)games.push([h,away]);else games.push([away,h]);}first.push(games);a=[a[0],a[n-1],...a.slice(1,n-1)]}return first.concat(first.map(round=>round.map(([h,a])=>[a,h])))}
function leagueClubs(tier,playerClub){let names=Object.keys(CLUBS).filter(n=>CLUBS[n][0]===tier);if(!names.includes(playerClub))names=names.filter(n=>n!==S?.formerClub).concat(playerClub);else names=names.filter(n=>n!==playerClub).concat(playerClub);let size=tier===2?22:20; if(names.length>size)names=names.filter(n=>n!==playerClub).slice(0,size-1).concat(playerClub);if(names.length<size){let extras=Object.keys(CLUBS).filter(n=>n!==playerClub&&!names.includes(n)).sort((a,b)=>Math.abs(CLUBS[a][1]-S.club.power)-Math.abs(CLUBS[b][1]-S.club.power));names.push(...extras.slice(0,size-names.length));}return names;}
function newSeasonSchedule(){let names=leagueClubs(S.club.tier,S.club.name);S.schedule=buildSchedule(names);S.table=newTable(names);S.round=0;S.week={training:false,life:false};S.lastResult=null;S.offers=[];S.story=null;S.match=null;S.agent={contract:false,market:false,minutes:false};S.stats={apps:0,starts:0,minutes:0,goals:0,assists:0,saves:0,tackles:0,clean:0,yellow:0,red:0,ratings:[],motm:0};S.results=[];S.view='hub';activeTab='hub';}
function create(){let name=($('name')?.value||'').trim().slice(0,28)||'Álex García',age=Number($('age')?.value||18),pos=$('position')?.value||'MC',club=$('club')?.value||'CE Sabadell',foot=$('foot')?.value||'Diestro',difficulty=$('difficulty')?.value||'realista',style=$('style')?.value||'equilibrado';let c=getClub(club),base=DEFAULT[pos];let bonus={equilibrado:{},tecnico:{pase:4,regate:4,fisico:-4,ritmo:-2},potente:{fisico:5,ritmo:3,pase:-3,regate:-2},goleador:{tiro:5,pase:-3,defensa:-2},tactico:{defensa:4,pase:3,tiro:-2,ritmo:-2}}[style]||{};let attrs=Object.fromEntries(SKILLS.map((k,i)=>[k,clamp(base[i]+(c.power-62)*.17+(bonus[k]||0)+rand(-3,3),8,90)]));S={version:2,player:{name,age,pos,foot,style,attrs,potential:int(81,92),fitness:92,morale:70,focus:70,trust:46,chemistry:58,rep:7,balance:1950,wage:Math.round(430+(c.power-60)*26),injured:0,suspension:0,contract:2},club:c,difficulty,year:2026,seasonNo:1,round:0,view:'hub',week:{training:false,life:false},story:null,match:null,inbox:[],history:[],results:[],awards:[],offers:[],pressAnswered:false};newSeasonSchedule();note('2026/27. Firmas con '+club+' en '+DIVS[c.tier].name+'. Tu primer objetivo será ganarte minutos.');persist();render();notify('¡Bienvenido al fútbol profesional!')}
function recordResult(h,a,hg,ag){let H=S.table[h],A=S.table[a];if(!H||!A)return;H.p++;A.p++;H.gf+=hg;H.ga+=ag;A.gf+=ag;A.ga+=hg;let x=hg>ag?'V':hg===ag?'E':'D';H.form.push(x);A.form.push(x==='V'?'D':x==='D'?'V':'E');if(hg>ag){H.w++;A.l++;H.pts+=3}else if(hg===ag){H.d++;A.d++;H.pts++;A.pts++}else{A.w++;H.l++;A.pts+=3}H.form=H.form.slice(-5);A.form=A.form.slice(-5)}
function sortedTable(){return Object.entries(S.table).map(([name,x])=>({name,...x})).sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga)||b.gf-a.gf||a.name.localeCompare(b.name))}
function upcoming(){let round=S.schedule[S.round];if(!round)return null;let pair=round.find(([h,a])=>h===S.club.name||a===S.club.name);return {home:pair[0]===S.club.name,opp:pair[0]===S.club.name?pair[1]:pair[0],pair}}
function poisson(lambda){let L=Math.exp(-lambda),k=0,p=1;do{k++;p*=Math.random()}while(p>L&&k<10);return Math.min(7,k-1)}
function simulateScore(home,away){let dif=(getClub(home).power-getClub(away).power)/15;let hg=poisson(clamp(1.37+dif*.45,.35,2.55)),ag=poisson(clamp(1.08-dif*.45,.3,2.5));return [hg,ag]}
function train(id){if(S.week.training||S.view!=='hub')return;let t=TRAININGS.find(x=>x.id===id);if(!t||id==='keeper'&&S.player.pos!=='POR')return;if(S.player.injured&&id!=='recover'){notify('Estás de baja. Solo puedes hacer recuperación.');return}let pre=S.player.fitness;for(let [k,v] of Object.entries(t.keys)){let att=S.player.attrs[k],ceiling=S.player.potential+(k==='porteria'&&S.player.pos!=='POR'?-40:5);let eff=clamp((ceiling-att)/27,.12,1.1);let ageFactor=S.player.age>29?.65:1;S.player.attrs[k]=Math.min(99,att+v*eff*rand(.8,1.3)*ageFactor)}mutate({fitness:t.fitness,trust:t.trust,focus:1});if((id==='gym'||id==='extra')&&pre<46&&Math.random()<(S.difficulty==='casual'?.06:.19)){S.player.injured=int(1,2);note('Has forzado demasiado con la carga. El fisio recomienda '+S.player.injured+' jornada(s) de baja.')}S.week.training=true;note('Entrenamiento: '+t.name+'. '+(t.fitness>0?'Recuperación física.':'Trabajo completado.'));persist();render();notify('Sesión completada')}
function life(id){if(S.week.life||S.view!=='hub')return;let t=LIFE.find(x=>x.id===id);if(!t)return;if(t.money<0&&S.player.balance<-t.money){notify('No tienes dinero suficiente.');return}mutate(Object.fromEntries(Object.entries(t).filter(([k])=>['fitness','morale','focus','chemistry','rep','trust','money'].includes(k))));if(t.extraSkill){let k=S.player.pos==='POR'?'porteria':pick(['ritmo','pase','tiro','regate','defensa','fisico']);S.player.attrs[k]=Math.min(99,S.player.attrs[k]+.26)}S.week.life=true;note('Fuera del campo: '+t.name+'.');persist();render();notify('Decisión registrada')}
function storyChoice(i){if(!S.story)return;let st=STORIES.find(x=>x.id===S.story);if(!st)return;let opt=st.opts[i];if(!opt)return;if(opt[1].money<0&&S.player.balance<-opt[1].money){notify('No puedes pagar esa opción.');return}mutate(opt[1]);note(st.title+': '+opt[2]);S.story=null;persist();render();notify(opt[2])}
