function startMatch(){let fixture=upcoming();if(!fixture)return;let p=S.player,ovr=overall(p),gap=ovr-S.club.power;let recent=recentRating();let realistic=S.difficulty!=='casual';let prob=clamp((realistic?.53:.70)+(gap/47)+(p.trust-55)/(realistic?145:115)+(p.fitness-78)/130+(recent?(.06*(recent-6.5)):0)+((p.chemistry-55)/500),.08,.94);let eligible=p.injured===0&&!(p.suspension>0);let start=eligible&&p.fitness>=46&&Math.random()<prob;let sub=!start&&eligible&&p.fitness>30&&Math.random()<(realistic?.53:.75)+p.trust/550;let enter=start?0:sub?pick([55,61,67,73,79]):-1;S.match={home:fixture.home,opp:fixture.opp,started:false,minute:0,step:0,enter,scoreUs:0,scoreThem:0,events:[],stats:{goals:0,assists:0,saves:0,tackles:0,passes:0,shots:0,yellow:0,errors:0},rating:6.3,tactics:'balance',finished:false,scenes:[],fitnessStart:p.fitness,press:false};S.view='match';persist();render()}
