function makeScenes(m){let role=POSITIONS[S.player.pos][1];if(S.player.pos==='LI'||S.player.pos==='LD')role='DEF';let pool=SCENES[role];let minutes=m.enter<=0?[9,20,32,44,56,68,78,87]:m.enter>0?[m.enter+3,Math.min(86,m.enter+12),Math.min(89,m.enter+20),89]:[];let shuffled=[...pool].sort(()=>Math.random()-.5);m.scenes=minutes.map((minute,i)=>({minute,scene:shuffled[i%shuffled.length],idx:i}));}
function playMatch(){let m=S.match;if(!m||m.started)return;m.started=true;makeScenes(m);if(m.enter===-1){m.events.push({minute:1,text:S.player.name+' no tendrá minutos. El entrenador opta por otras alternativas.',highlight:false});quickMatch();return}if(m.enter>0)m.events.push({minute:1,text:'Empiezas como suplente. El equipo juega hasta el minuto '+m.enter+'.',highlight:false});else m.events.push({minute:1,text:'¡Rueda el balón! Sales de inicio con el '+S.club.name+(S.club.name==='CE Sabadell'&&m.home?' en la Nova Creu Alta.':'.'),highlight:false});m.minute=0;ambient(m.scenes[0]?.minute||90,m);persist();render()}
function chance(skill,diff,game){let value=skill==='focus'?S.player.focus:S.player.attrs[skill]||50;let pressure=S.club.power-getClub(game.opp).power;let tactics=game.tactics==='attack'?.025:game.tactics==='calm'?.025:0;let difficulty=S.difficulty==='casual'?.065:-.03;return clamp(.49+(value-62)*.0098-diff*.27+(S.player.morale-60)*.0018+(S.player.focus-60)*.001+(S.player.fitness-65)*.0015+pressure*.002+(S.player.chemistry-60)*.0007+tactics+difficulty,.09,.85)}
function log(minute,text,highlight=false){S.match.events.push({minute,text,highlight});S.match.events=S.match.events.slice(-26)}
function ambient(target,m){let from=m.minute||0,oppPower=getClub(m.opp).power,teamPower=S.club.power;for(let t=Math.max(from+1,1);t<=target;t+=8){let st=Math.max(0,(oppPower-teamPower)/25);let homeBoost=m.home?.012:0;let us=.055+(teamPower-oppPower)/420+homeBoost;let them=.053+(oppPower-teamPower)/390-homeBoost;if(m.tactics==='attack'){us+=.013;them+=.015}if(m.tactics==='calm'){us-=.005;them-=.006}if(Math.random()<clamp(us,.012,.14)){m.scoreUs++;log(Math.min(t,target),'¡GOL de '+S.club.name+'! El equipo aprovecha una jugada colectiva.',true)}if(Math.random()<clamp(them,.012,.15)){m.scoreThem++;log(Math.min(t,target),'Marca '+m.opp+' tras una ocasión de peligro.',true)}}m.minute=target;}
function resolveChoice(index){let m=S.match;if(!m||!m.started||m.finished)return;let item=m.scenes[m.step];if(!item)return;let opt=item.scene.opts[index];if(!opt)return;let [txt,skill,type,diff]=opt,success=Math.random()<chance(skill,diff,m),p=S.player,st=m.stats;let drain=m.tactics==='attack'?4:m.tactics==='calm'?1.5:2.5;p.fitness=clamp(p.fitness-drain);let msg='';let ratingDelta=0;
if(type==='goal'){
st.shots++;if(success&&Math.random()<(.38+(p.attrs.tiro-60)*.003)){m.scoreUs++;st.goals++;ratingDelta=1.3;msg='¡GOOOOL! '+p.name+' la manda a guardar. La grada estalla.';}else if(success){ratingDelta=.10;msg='Buen intento. El portero evita el gol o se marcha rozando el palo.';}else{ratingDelta=-.18;msg='La ocasión se escapa. No consigues rematar con claridad.';}
}else if(type==='assist'){
if(success&&Math.random()<.36){m.scoreUs++;st.assists++;ratingDelta=.84;msg='¡Asistencia! Tu pase deja un remate servido y el equipo marca.';}else if(success){st.passes++;ratingDelta=.20;msg='Gran balón: creas peligro, pero el remate no acaba dentro.';}else{ratingDelta=-.16;msg='La defensa intercepta el pase antes de que llegue al destinatario.';}
}else if(type==='defend'){
if(success){st.tackles++;ratingDelta=.32;msg='¡Intervención decisiva! Cortas la jugada rival limpiamente.';}else{ratingDelta=-.33;msg='Te superan y el rival genera una ocasión comprometida.';if(Math.random()<.28){m.scoreThem++;msg+=' Terminan marcando.';st.errors++;ratingDelta-=.4}}
}else if(type==='save'){
if(success){st.saves++;ratingDelta=.5;msg='¡PARADÓN! Evitas un gol que parecía cantado.';}else{ratingDelta=-.37;m.scoreThem++;st.errors++;msg='No consigues detener el remate. Gol del equipo rival.';}
}else if(type==='foul'){
let y=Math.random()<.54;if(y){st.yellow++;ratingDelta=-.17}if(success){ratingDelta+=.06;msg='Falta táctica. Frena el avance rival'+(y?', pero ves la amarilla.':'.')}else{ratingDelta-=.32;msg='Llegas tarde y el rival conserva el peligro'+(y?'. Tarjeta amarilla.':'.');if(Math.random()<.17){m.scoreThem++;msg+=' La acción termina en gol.'}}
}else if(type==='attack'){
if(success){ratingDelta=.28;st.passes++;msg='Superas líneas y el ataque progresa. Buen movimiento.';if(Math.random()<.13){m.scoreUs++;st.assists++;ratingDelta+=.6;msg+=' ¡La jugada termina en gol y te apuntan una asistencia!'}}else{ratingDelta=-.29;msg='Pierdes el balón. Tus compañeros deben rehacerse en defensa.';if(Math.random()<.14){m.scoreThem++;msg+=' El rival castiga la pérdida.'}}
}else{
if(success){ratingDelta=.12;st.passes++;msg='Juegas con cabeza. El equipo mantiene la pelota.';}else{ratingDelta=-.10;msg='El rival lee el pase y recupera la posesión.';}}
if(m.tactics==='attack')ratingDelta+=success?.04:-.04;if(m.tactics==='calm')ratingDelta+=success?.03:0;
m.rating=clamp(m.rating+ratingDelta,3,10);log(item.minute,txt+' — '+msg,success&&['goal','assist','save'].includes(type));if(st.yellow>=2){m.sentOff=true;m.exitMinute=item.minute;log(item.minute,'¡Segunda amarilla! El árbitro te expulsa. Tus compañeros deberán seguir con uno menos.',true);if(Math.random()<.34){m.scoreThem++;log(item.minute+1,'El rival aprovecha la superioridad numérica y marca.',true)}ambient(90,m);finishMatch();persist();render();return;}m.step++;let next=m.scenes[m.step];if(next){ambient(next.minute,m)}else{ambient(90,m);finishMatch()}persist();render()}
function quickMatch(){let m=S.match;if(!m)return;if(!m.started){m.started=true;makeScenes(m)}if(m.enter===-1){ambient(90,m);finishMatch();return}while(m.step<m.scenes.length&&!m.sentOff){let scene=m.scenes[m.step];if(m.minute<scene.minute)ambient(scene.minute,m);let opts=scene.scene.opts;let idx=m.tactics==='attack'?pick([0,0,1,2]):m.tactics==='calm'?pick([1,2,2,2]):pick([0,1,2]);resolveQuick(idx);}
ambient(90,m);finishMatch();}
function resolveQuick(i){let m=S.match,item=m.scenes[m.step],opt=item.scene.opts[i];let [txt,skill,type,diff]=opt;let success=Math.random()<chance(skill,diff,m);S.player.fitness=clamp(S.player.fitness-(m.tactics==='attack'?4:2.5));let delta=0; if(type==='goal'){m.stats.shots++;if(success&&Math.random()<.40){m.scoreUs++;m.stats.goals++;delta=1.18;log(item.minute,'¡GOL de '+S.player.name+'!',true)}else delta=success?.12:-.15}else if(type==='assist'||type==='attack'){if(success&&Math.random()<.25){m.scoreUs++;m.stats.assists++;delta=.81;log(item.minute,'Asistencia de '+S.player.name+'.',true)}else delta=success?.19:-.13}else if(type==='save'){if(success){m.stats.saves++;delta=.45}else{m.scoreThem++;m.stats.errors++;delta=-.42;log(item.minute,'El rival marca tras una ocasión clara.',true)}}else if(type==='defend'){if(success){m.stats.tackles++;delta=.3}else{delta=-.25;if(Math.random()<.23){m.scoreThem++;m.stats.errors++;log(item.minute,'Gol rival tras un desajuste defensivo.',true)}}}else if(type==='foul'){if(Math.random()<.4)m.stats.yellow++;delta=success?.03:-.2}else{delta=success?.13:-.1}m.rating=clamp(m.rating+delta,3,10);m.step++;if(m.stats.yellow>=2){m.sentOff=true;m.exitMinute=item.minute;log(item.minute,'Segunda tarjeta amarilla. ¡Expulsado!',true)}if(!m.sentOff&&m.scenes[m.step])ambient(m.scenes[m.step].minute,m)}
function finishMatch(){let m=S.match;if(m.finished)return;m.finished=true;m.minute=90;let p=S.player,st=m.stats;let min=m.enter<0?0:m.sentOff?Math.max(0,m.exitMinute-m.enter):m.enter===0?90:90-m.enter;let star=min>0&&m.rating>=8.8;if(min===0)m.rating=0;else{m.rating=clamp(m.rating+(m.scoreUs>m.scoreThem?.12:m.scoreUs<m.scoreThem?-.12:0),3,10);p.trust=clamp(p.trust+(m.rating-6.7)*2.2+(m.tactics==='calm'?0:0));p.morale=clamp(p.morale+(m.scoreUs>m.scoreThem?5:m.scoreUs<m.scoreThem?-5:1)+(m.rating-7)*1.3);p.rep=clamp(p.rep+(st.goals*2.8+st.assists*1.7+(m.rating>=8?3:0)));p.focus=clamp(p.focus-1);p.fitness=clamp(p.fitness-(min>=85?10:5));}
let stat=S.stats;if(min>0){stat.apps++;if(m.enter===0)stat.starts++;stat.minutes+=min;stat.goals+=st.goals;stat.assists+=st.assists;stat.saves+=st.saves;stat.tackles+=st.tackles;stat.yellow+=st.yellow;stat.ratings.push(m.rating);if(star){stat.motm++;note('¡Jugador del partido! Tu rendimiento destaca ante '+m.opp+'.')}}if(m.sentOff){stat.red++;p.suspension=Math.max(p.suspension||0,1);p.trust=clamp(p.trust-7);note('Sanción: expulsión por doble amonestación. Te perderás el siguiente partido.')}else if(stat.yellow>0&&stat.yellow%5===0&&st.yellow){p.suspension=Math.max(p.suspension||0,1);note('Cinco tarjetas amarillas acumuladas: un partido de sanción.')}if(m.enter<0&&p.suspension>0)p.suspension--;if(min>0&&p.fitness<33&&Math.random()<(S.difficulty==='casual'?.025:.075)){p.injured=int(1,3);note('Informe médico tras el encuentro: molestias musculares. Deberás descansar.')}if(m.scoreThem===0&&min>0)stat.clean++;
let {pair}=upcoming(),[h,a]=pair;let hg=m.home?m.scoreUs:m.scoreThem,ag=m.home?m.scoreThem:m.scoreUs;recordResult(h,a,hg,ag);for(let [ho,aw] of S.schedule[S.round]){if(ho===S.club.name||aw===S.club.name)continue;let [g1,g2]=simulateScore(ho,aw);recordResult(ho,aw,g1,g2)}
S.lastResult={opp:m.opp,home:m.home,us:m.scoreUs,them:m.scoreThem,rating:m.rating,minutes:min,goals:st.goals,assists:st.assists,save:st.saves};S.results.push({...S.lastResult,round:S.round+1});m.events.push({minute:90,text:'Final del partido. '+(m.scoreUs>m.scoreThem?'¡Victoria!':m.scoreUs<m.scoreThem?'Derrota.':'Reparto de puntos.'),highlight:true});S.view='post';S.pressAnswered=false;note('Jornada '+(S.round+1)+': '+S.club.name+' '+m.scoreUs+' - '+m.scoreThem+' '+m.opp+'.'+(min?' Nota '+m.rating.toFixed(1)+'.':' Sin minutos.'));persist();render()}
function press(kind){if(S.pressAnswered)return;let choices={team:[{trust:3,chemistry:3,rep:1},'Pones el foco en el equipo.'],bold:[{rep:5,trust:-3,focus:-3},'Tu ambición se convierte en noticia.'],honest:[{trust:2,focus:3,morale:-1},'Reconoces dónde se puede mejorar.'],silent:[{focus:3,rep:-2},'Decides no hablar.']};let c=choices[kind];if(!c)return;mutate(c[0]);S.pressAnswered=true;note('Zona mixta: '+c[1]);persist();render();notify(c[1])}
function nextWeek(){if(S.view!=='post')return;S.round++;let p=S.player;let overhead=S.stage==='academy'?Math.min(25,p.wage*.28):p.wage<1600?Math.min(110,p.wage*.27):p.wage*.14;p.balance+=p.wage-overhead;p.fitness=clamp(p.fitness+rand(15,23)+(S.difficulty==='casual'?4:0));p.morale=clamp(p.morale+rand(-2,2));p.focus=clamp(p.focus+rand(-1,2));if(p.injured>0){p.injured--;if(p.injured===0)note('Parte médico: recibes el alta competitiva.')}S.match=null;S.week={training:false,life:false};if(S.round>=S.schedule.length){seasonEnd();return}if((S.round%3===0||Math.random()<.19)&&!S.story)S.story=pick(STORIES).id;S.view='hub';activeTab='hub';persist();render()}
function recentRating(){let r=S.stats.ratings.slice(-5);return r.length?r.reduce((a,b)=>a+b,0)/r.length:0}
function leagueRules(tier,size){return tier===1?{auto:0,playoff:[0,0],drop:3,desc:'El campeón gana LaLiga; los 3 últimos bajan a Segunda.'}:tier===2?{auto:2,playoff:[3,6],drop:4,desc:'1.º y 2.º ascienden; del 3.º al 6.º juegan el playoff. Los 4 últimos descienden.'}:{auto:1,playoff:[2,5],drop:5,desc:'1.º asciende; del 2.º al 5.º juega el playoff. Los 5 últimos pierden la categoría (la Segunda Federación no se simula).'}}
function seasonGoal(){let p=S.player;return {minutes:Math.round((S.schedule?.length||38)*38),avg:6.65,goals:['DC','EI','ED'].includes(p.pos)?Math.ceil((S.schedule?.length||38)/7):0,assists:['MCO','MC','MCD'].includes(p.pos)?Math.ceil((S.schedule?.length||38)/8):0,saves:p.pos==='POR'?Math.ceil((S.schedule?.length||38)*.65):0}}
function seasonGoalStatus(){let g=seasonGoal(),st=S.stats;let lines=[['Minutos',st.minutes,g.minutes],['Nota media',Number(avgRating().toFixed(2)),g.avg]];if(g.goals)lines.push(['Goles',st.goals,g.goals]);if(g.assists)lines.push(['Asistencias',st.assists,g.assists]);if(g.saves)lines.push(['Paradas',st.saves,g.saves]);return lines}
function avgRating(){return S.stats.ratings.length?S.stats.ratings.reduce((a,b)=>a+b,0)/S.stats.ratings.length:0}
function seasonEnd(){let table=sortedTable(),rank=table.findIndex(t=>t.name===S.club.name)+1,stats=S.stats;let avg=avgRating(),rules=leagueRules(S.club.tier,table.length);let promoted=false,relegated=false,playoffs=false,playoffResult='';if(S.club.tier===2){promoted=rank<=2;playoffs=rank>=3&&rank<=6;relegated=rank>=table.length-3;}else if(S.club.tier===3){promoted=rank===1;playoffs=rank>=2&&rank<=5;}else{relegated=rank>=table.length-2;}if(playoffs){let chancePO=clamp(.23+(avg-6.7)*.065+(S.club.power-70)*.011,.14,.47);promoted=Math.random()<chancePO;playoffResult=promoted?'¡Ganas el playoff de ascenso!':'Caes eliminado en el playoff de ascenso.';note(playoffResult)}let pos=rank===1?'campeonato':promoted?'ascenso':playoffs?'playoff de ascenso':relegated?'descenso':rank>=table.length-5?'lucha por la permanencia':'permanencia';let awards=[];if(avg>=8&&stats.apps>=8)awards.push('En el once ideal de la competición');if(stats.goals>=15)awards.push('Máximo referente goleador del club');if(stats.assists>=11)awards.push('Líder de asistencias del equipo');if(rank===1)awards.push('Campeón de liga');if(promoted)awards.push('Ascenso de categoría');if(seasonGoalStatus().every(([name,val,target])=>val>=target)){awards.push('Objetivos personales cumplidos');S.player.rep=clamp(S.player.rep+7);S.player.balance+=Math.round(S.player.wage*1.5);note('¡Cumples los objetivos de temporada! Prima deportiva y reputación adicional.')}S.awards.push(...awards.map(a=>({year:S.year,title:a})));S.history.push({year:S.year,club:S.club.name,tier:S.club.tier,rank,played:stats.apps,goals:stats.goals,assists:stats.assists,avg:Number(avg.toFixed(2)),award:awards.join(', '),promoted,relegated});S.seasonSummary={rank,played:stats.apps,goals:stats.goals,assists:stats.assists,avg,minutes:stats.minutes,position:pos,promoted,relegated,awards,points:table[rank-1].pts,playoffResult};if(promoted&&S.club.tier>1){S.club.tier--;S.club.power+=4;note('¡Ascenso! '+S.club.name+' jugará en '+DIVS[S.club.tier].name+'.')}if(relegated&&S.club.tier<3){S.club.tier++;S.club.power-=4;note('El club desciende a '+DIVS[S.club.tier].name+'.')}S.offers=generateOffers();S.view='season';persist();render()}
function generateOffers(){let p=S.player,ov=overall(p),avg=S.seasonSummary.avg;let repBoost=p.rep*.15,targets=[];for(let [name,data] of Object.entries(CLUBS)){if(name===S.club.name)continue;let [tier,pow]=data;if(tier<S.club.tier-1)continue;if(pow>ov+11+(avg>7.5?5:0))continue;if(tier===1&&ov<70)continue;if(tier===2&&ov<63)continue;if(tier===3&&S.club.tier===1)continue;let attractiveness=38-Math.abs(pow-ov)*1.7+(S.club.tier-tier)*10+repBoost/6;targets.push({name,tier,power:pow,weight:attractiveness})}
targets.sort((a,b)=>b.weight-a.weight);let viable=targets.filter(c=>c.weight>12).slice(0,12);let count=S.seasonNo===1?2:3;let selection=[];while(viable.length&&selection.length<count){let idx=int(0,Math.min(viable.length-1,5));selection.push(viable.splice(idx,1)[0])}return selection.map(c=>({name:c.name,tier:c.tier,power:c.power,wage:Math.round((380+(c.power-58)*95+(ov-59)*34)*(rand(.92,1.12))/10)*10,contract:int(2,4),accepted:false}))}
function acceptOffer(idx){if(S.view!=='season'||!S.offers[idx])return;S.accepted=idx;persist();render();notify('Has elegido destino. Confirma para comenzar la temporada.')}
function beginSeason(){if(S.view!=='season')return;let p=S.player,old=S.club.name;let idx=S.accepted;if(idx!==undefined&&S.offers[idx]){let o=S.offers[idx];S.club={...getClub(o.name),tier:o.tier,power:o.power};p.wage=o.wage;p.contract=o.contract;note('Fichaje confirmado. Nuevo club: '+o.name+'. Salario: '+money(o.wage)+'/semana.');}else{p.contract--;p.wage=Math.round(p.wage*(1+(S.seasonSummary.avg>=7.2?.15:.04)));if(p.contract<=0)p.contract=2;note('Continúas en '+S.club.name+'. El club revisa las condiciones de tu contrato.');}p.age++;p.fitness=clamp(p.fitness+30);p.morale=clamp(p.morale+10);p.focus=clamp(p.focus+8);p.injured=0;p.suspension=0;S.year++;S.seasonNo++;S.accepted=undefined;newSeasonSchedule();note('Arranca la temporada '+S.year+'/'+(S.year+1)+'. '+(old!==S.club.name?'Nueva ciudad, nuevo reto.':'Nueva oportunidad para crecer.'));persist();render();notify('¡Nueva temporada!')}
function reset(){if(!confirm('¿Borrar la carrera actual? Perderás el progreso guardado en este navegador.'))return;S=null;activeTab='hub';store.removeItem(SAVE_KEY);render()}
function exportGame(){if(!S)return;let blob=new Blob([JSON.stringify(S,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='fuera-de-guion-'+S.player.name.toLowerCase().replace(/[^a-z0-9]+/gi,'-')+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function importGame(){const file=$('importFile').files[0];if(!file)return;let reader=new FileReader();reader.onload=()=>{try{let s=JSON.parse(reader.result);if(!s?.player?.attrs||!s?.club?.name||!Array.isArray(s.schedule)||!s.table||!s.stats||s.version!==3)throw Error('Archivo incompatible');S=s;activeTab='hub';persist();render();notify('Carrera restaurada.')}catch(e){alert('No se pudo importar la partida: '+e.message)}$('importFile').value=''};reader.readAsText(file)}
function avgCap(n){return Number(n).toFixed(1)}
function statUI(label,value){return `<div class="metric"><strong>${value}</strong><span>${label}</span></div>`}
function bar(n,color){return `<div class="bar"><i style="width:${clamp(n)}%;${color?'background:'+color:''}"></i></div>`}
function badge(s,kind=''){return `<span class="tag ${kind}">${s}</span>`}
function playerStatus(){let p=S.player;return `<div class="card"><div class="profiletop"><div class="avatar">${esc(initials(p.name))}</div><div style="flex:1;min-width:0"><div class="eyebrow">${S.stage==='academy'?'Futbolista juvenil':'Futbolista profesional'}</div><h3 style="margin:3px 0 2px;font-size:19px;overflow-wrap:anywhere">${esc(p.name)}</h3><span class="muted" style="font-size:12px">${p.pos} · ${p.age} años · ${esc(p.foot)}</span></div><div><div class="ovr">${overall(p)}</div><div class="micro" style="text-align:center">MEDIA</div></div></div><hr class="divider"><div class="statrow"><span>Condición física</span><strong style="color:${colorRank(p.fitness)}">${Math.round(p.fitness)}%</strong></div>${bar(p.fitness)}<div class="statrow"><span>Confianza del míster</span><strong>${Math.round(p.trust)}/100</strong></div>${bar(p.trust)}<div class="statrow"><span>Moral</span><strong>${Math.round(p.morale)}/100</strong></div>${bar(p.morale)}<div class="statrow"><span>Concentración</span><strong>${Math.round(p.focus)}/100</strong></div>${bar(p.focus)}${p.injured?`<div class="alert red" style="margin-top:13px">Parte médico: baja durante ${p.injured} ${p.injured===1?'partido':'partidos'}.</div>`:''}${p.suspension>0?`<div class="alert warn" style="margin-top:13px">Suspendido: ${p.suspension} partido sin jugar.</div>`:''}</div>`}
function clubSide(){let cur=upcoming(),rank=S.table?sortedTable().findIndex(x=>x.name===S.club.name)+1:0;return `<div class="card"><div class="eyebrow">Tu club</div><h3 style="font-size:21px;margin:7px 0 4px">${esc(S.club.name)}</h3><p class="muted" style="font-size:12px">${DIVS[S.club.tier].name} · ${S.year}/${S.year+1}</p>${S.club.name==='CE Sabadell'?'<div class="tag green" style="margin-bottom:12px">🏟 Nova Creu Alta</div>':''}<div class="cols2" style="gap:8px"><div class="metric"><strong>${S.round===0?'—':rank||'—'}<small style="font-size:13px">º</small></strong><span>Posición</span></div><div class="metric"><strong>${S.table[S.club.name]?.pts||0}</strong><span>Puntos</span></div></div>${cur?`<div style="margin-top:18px"><div class="label">Próximo rival · J${S.round+1}</div><h3 style="margin:0 0 7px">${esc(cur.opp)}</h3><span class="micro">${cur.home?'En casa · juegas como local':'Fuera de casa · visitas al rival'}</span></div>`:'<p class="micro">Temporada concluida.</p>'}</div>`}
function inboxUI(){return `<div class="card"><div class="sectionhead"><h3>Noticias de tu carrera</h3>${badge('Últimas 5')}</div>${(S.inbox||[]).slice(0,5).map(item=>`<div class="inbox"><span class="eyebrow">${S.year} · J${item.round}</span><br>${esc(item.text)}</div>`).join('')||'<p class="empty">Aún no hay noticias.</p>'}</div>`}
function navigation(){let nav=[['hub','Vestuario'],['player','Mi jugador'],['league','Clasificación'],['agent','Representante'],['history','Trayectoria']];return `<div class="tabs">${nav.map(([k,l])=>`<button class="tab ${activeTab===k?'active':''}" onclick="Game.tab('${k}')">${l}</button>`).join('')}</div>`}
function sectionChoice(items,used,type){return `<div class="cols2">${items.map(t=>`<button class="pick ${used?'': ''}" onclick="Game.${type}('${t.id}')" ${used?'disabled':''}><strong>${esc(t.name)} ${used?'✓':''}</strong><small>${esc(t.desc)}</small></button>`).join('')}</div>`}
function storyUI(){if(!S.story)return '';let st=STORIES.find(x=>x.id===S.story);if(!st)return '';return `<div class="eventBox" style="margin:16px 0"><div class="eyebrow">Decisión fuera del campo · Importante</div><h3 style="margin:8px 0">${esc(st.title)}</h3><p>${esc(st.text)}</p><div class="grid" style="gap:9px">${st.opts.map(([name,changes],i)=>`<button class="pick" onclick="Game.story(${i})"><strong>${esc(name)}</strong><small>${effectsText(changes)}</small></button>`).join('')}</div></div>`}
function effectsText(ch){return Object.entries(ch).map(([k,v])=>{let names={trust:'Confianza',fitness:'Físico',morale:'Moral',focus:'Concentración',rep:'Reputación',chemistry:'Vestuario',money:'Dinero',wage:'Salario',injuryChance:'Riesgo de lesión'};return `${names[k]||k} ${v>0?'+':''}${k==='money'||k==='wage'?money(v):k==='injuryChance'?Math.round(v*100)+'%':v}`}).join(' · ')}
function hubLegacy(){let p=S.player,u=upcoming(),s=S.stats,r=avgRating(),stand=sortedTable(),rank=stand.findIndex(x=>x.name===S.club.name)+1;return `${navigation()}<div class="hero card"><div style="z-index:1;position:relative"><div class="eyebrow" style="margin-bottom:13px">Capítulo ${S.seasonNo} · Jornada ${S.round+1} de ${S.schedule.length} · ${S.difficulty==='casual'?'Casual':'Realista'}</div><h1>Tu historia.<br><span style="color:var(--accent)">Tus decisiones.</span></h1><p class="bigmuted" style="line-height:1.7">${esc(p.name)}, ${p.age} años. ${esc(S.club.name)}. Un partido puede cambiarlo todo, pero tu carrera se construye también entre semana.</p><div class="actions"><button class="btn" onclick="Game.matchPre()">⚽ Preparar partido ${S.round+1}</button><button class="btn secondary" onclick="Game.tab('league')">Ver la liga</button></div></div><div class="metrics" style="position:relative;z-index:1;display:grid;grid-template-columns:1fr 1fr;gap:9px">${statUI('Goles',s.goals)}${statUI('Asistencias',s.assists)}${statUI('Partidos',s.apps)}${statUI('Nota media',r?r.toFixed(1):'—')}</div></div><div style="margin-top:15px" class="smallgrid">${statUI('Jornada',S.round+1)}${statUI('Liga',(S.round===0?'—':rank+'º'))}${statUI('Confianza',Math.round(p.trust))}${statUI('Saldo',money(p.balance))}</div>${storyUI()}<div class="card" style="margin-top:16px"><div class="sectionhead"><h3>Objetivos de la temporada</h3>${badge('Contrato / Rendimiento','green')}</div><div class="cols2">${seasonGoalStatus().map(([name,val,target])=>`<div><div class="statrow"><span>${name}</span><strong>${typeof val==='number'&&name==='Nota media'?val.toFixed(2):fmt(val)} / ${target}</strong></div>${bar(Math.min(100,Math.round((val/target)*100)))}</div>`).join('')}</div><p class="micro" style="margin-top:12px">Cumplir todos los objetivos al final del curso da una prima y mejora tu reputación. No garantizan un puesto en el once.</p></div><div class="cols2" style="margin-top:16px"><div class="card"><div class="sectionhead"><div><div class="eyebrow">Preparación · 1 por jornada</div><h3 style="margin:5px 0 0">Centro de entrenamiento</h3></div>${badge(S.week.training?'Completado':'Disponible',S.week.training?'green':'')}</div><p class="micro">Mejora habilidades con el tiempo. Entrenar fatigado tiene consecuencias: controla las cargas.</p>${sectionChoice(TRAININGS.filter(t=>t.id!=='keeper'||p.pos==='POR'),S.week.training,'train')}</div><div class="card"><div class="sectionhead"><div><div class="eyebrow">Vida personal · 1 por jornada</div><h3 style="margin:5px 0 0">Fuera del césped</h3></div>${badge(S.week.life?'Completado':'Disponible',S.week.life?'green':'')}</div><p class="micro">Tu reputación, descanso, amistades y economía también juegan. Cada acción tiene un coste.</p>${sectionChoice(LIFE,S.week.life,'life')}</div></div><div class="card" style="margin-top:16px"><div class="sectionhead"><h3>El siguiente desafío</h3>${badge(u.home?'LOCAL':'VISITANTE')}</div><div style="display:flex;align-items:center;justify-content:space-between;gap:15px;flex-wrap:wrap"><div><div class="eyebrow">${leagueLabel()} · J${S.round+1}</div><div style="font:900 23px Outfit;margin:9px 0">${esc(S.club.name)} <span class="muted" style="font-size:14px">vs</span> ${esc(u.opp)}</div><span class="micro">${u.home?'Estadio local':'Estadio rival'} · ${Math.round(p.fitness)}% de forma física</span></div><button class="btn" onclick="Game.matchPre()">Ir al partido →</button></div></div>`}
function profile(){let p=S.player,overallValue=overall(p);let pos=POSITIONS[p.pos],x=(p.pos==='POR'?50:p.pos==='DC'?73:['EI','ED'].includes(p.pos)?73:['MCO'].includes(p.pos)?60:['MC','MCD'].includes(p.pos)?48:['LI','LD'].includes(p.pos)?28:23),y=(p.pos==='EI'||p.pos==='LI')?20:(p.pos==='ED'||p.pos==='LD')?80:50;return `${navigation()}<div class="cols2"><div class="card"><div class="eyebrow">Ficha del futbolista</div><div class="profiletop" style="margin:20px 0"><div class="avatar" style="width:82px;height:82px;font-size:37px">${esc(initials(p.name))}</div><div style="flex:1"><h2 style="margin:0">${esc(p.name)}</h2><p class="muted" style="font-size:13px">${esc(pos[0])} · ${p.age} años</p>${badge(p.pos,'green')} ${badge(p.foot)}</div><div><div class="ovr">${overallValue}</div><span class="micro">MEDIA</span></div></div><div class="linefield" style="margin:15px 0"><div class="circle" style="left:${x}%;top:${y}%"></div><div style="position:absolute;border:2px solid #ffffff55;width:18%;height:50%;left:6%;top:25%"></div><div style="position:absolute;border:2px solid #ffffff55;width:18%;height:50%;right:6%;top:25%"></div></div><div class="statrow"><span>Potencial estimado</span><strong>${p.potential}</strong></div><div class="statrow"><span>Valor de mercado aproximado</span><strong>${money(marketValue())}</strong></div><div class="statrow"><span>Salario semanal</span><strong>${money(p.wage)}</strong></div><div class="statrow"><span>Contrato restante</span><strong>${p.contract} ${p.contract===1?'año':'años'}</strong></div></div><div class="card"><div class="sectionhead"><h3>Atributos</h3>${badge('Entrenables')}</div>${SKILLS.filter(k=>k!=='porteria'||p.pos==='POR').map(k=>`<div class="skill"><span>${ATTRS[k]}</span>${bar(p.attrs[k])}<b style="color:${colorRank(p.attrs[k])}">${Math.round(p.attrs[k])}</b></div>`).join('')}<hr class="divider"><div class="eyebrow">Mentalidad y contexto</div>${[['Condición',p.fitness],['Moral',p.morale],['Concentración',p.focus],['Confianza técnica',p.trust],['Química vestuario',p.chemistry],['Reputación',p.rep]].map(([l,v])=>`<div class="statrow"><span>${l}</span><strong>${Math.round(v)}/100</strong></div>`).join('')}<p class="micro" style="margin:12px 0 0;line-height:1.6">El potencial representa una previsión de tus capacidades, no una garantía. El desarrollo depende de los entrenamientos y las oportunidades.</p></div></div><div class="card" style="margin-top:16px"><div class="sectionhead"><h3>Temporada ${S.year}/${S.year+1}</h3>${badge(DIVS[S.club.tier].short)}</div><div class="smallgrid">${statUI('Partidos',S.stats.apps)}${statUI('Goles',S.stats.goals)}${statUI('Asist.',S.stats.assists)}${statUI('Nota',avgRating()?avgRating().toFixed(1):'—')}</div><hr class="divider"><div class="statrow"><span>Minutos disputados</span><strong>${S.stats.minutes}</strong></div><div class="statrow"><span>Titularidades</span><strong>${S.stats.starts}</strong></div><div class="statrow"><span>Entradas y recuperaciones</span><strong>${S.stats.tackles}</strong></div><div class="statrow"><span>Paradas (portero)</span><strong>${S.stats.saves}</strong></div><div class="statrow"><span>Porterías a cero (en campo)</span><strong>${S.stats.clean}</strong></div><div class="statrow"><span>Tarjetas amarillas</span><strong>${S.stats.yellow}</strong></div><div class="statrow"><span>Expulsiones</span><strong>${S.stats.red}</strong></div><div class="statrow"><span>MVP de partido</span><strong>${S.stats.motm}</strong></div></div>`}
function marketValue(){let p=S.player,ov=overall(p);return Math.round(28000*Math.pow(1.18,ov-58)*(p.age<24?1.2:p.age>30?.68:1)*(1+p.rep*.011)*(S.club.tier===1?2.5:S.club.tier===2?1.4:1)/1000)*1000}
function leagueTable(){return `<div style="overflow-x:auto"><table class="league"><thead><tr><th style="text-align:left;width:24px">#</th><th style="text-align:left">Equipo</th><th>PJ</th><th>G</th><th>E</th><th>P</th><th>GF</th><th>GC</th><th>DG</th><th>Pts</th></tr></thead><tbody>${sortedTable().map((x,i)=>`<tr class="${x.name===S.club.name?'you':''} ${(S.club.tier===1?i===0:S.club.tier===2?i<2:i===0)?'promo':i>=sortedTable().length-leagueRules(S.club.tier,sortedTable().length).drop?'drop':''}"><td style="text-align:left">${i+1}</td><td>${esc(x.name)}${x.name===S.club.name?' ★':''}</td><td>${x.p}</td><td>${x.w}</td><td>${x.d}</td><td>${x.l}</td><td>${x.gf}</td><td>${x.ga}</td><td>${x.gf-x.ga>0?'+':''}${x.gf-x.ga}</td><td><strong>${x.pts}</strong></td></tr>`).join('')}</tbody></table></div>`}
function leagueViewLegacy(){let u=upcoming(),last=S.results.slice(-6).reverse();return `${navigation()}<div class="card"><div class="sectionhead"><div><div class="eyebrow">Temporada ${S.year}/${S.year+1}</div><h2 style="margin:6px 0 0">${DIVS[S.club.tier].name}</h2></div>${badge('J'+Math.min(S.round+1,S.schedule.length)+' / '+S.schedule.length,'green')}</div>${leagueTable()}<div class="micro" style="margin-top:14px;line-height:1.5">${leagueRules(S.club.tier,Object.keys(S.table).length).desc} Doble vuelta, ida y vuelta; los resultados y acontecimientos son simulados.</div></div><div class="cols2" style="margin-top:16px"><div class="card"><h3>Últimos partidos</h3>${last.length?last.map(r=>`<div class="fixture"><div class="names"><strong>J${r.round}</strong> · ${esc(r.opp)}<div class="micro">${r.home?'Local':'Visitante'} · Nota ${r.minutes?r.rating.toFixed(1):'—'}</div></div><div class="score" style="color:${r.us>r.them?'var(--accent)':r.us<r.them?'var(--red)':'white'}">${r.us} : ${r.them}</div></div>`).join(''):'<p class="empty">El balón todavía no ha rodado.</p>'}</div><div class="card"><h3>Próximas jornadas</h3>${S.schedule.slice(S.round,S.round+7).map((round,i)=>{let a=round.find(([h,aw])=>h===S.club.name||aw===S.club.name);if(!a)return '';let opp=a.find(n=>n!==S.club.name);return `<div class="fixture"><div class="names"><strong>J${S.round+i+1}</strong> · ${esc(opp)}<div class="micro">${a[0]===S.club.name?'En casa':'A domicilio'}</div></div><span class="tag">${getClub(opp).power} OVR eq.</span></div>`}).join('')||'<p class="empty">Calendario terminado.</p>'}</div></div>`}
function agentAction(kind){if(S.view!=='hub')return;S.agent=S.agent||{contract:false,market:false,minutes:false};if(S.agent[kind])return;let p=S.player,ov=overall(p);let msg='';if(kind==='contract'){S.agent.contract=true;if(S.round>=7&&p.trust>=55&&avgRating()>=6.7&&Math.random()<.7){let boost=Math.round(p.wage*rand(.09,.18));p.wage+=boost;msg='El club acepta aumentar tu salario '+money(boost)+'/semana.';p.morale=clamp(p.morale+5)}else{p.trust=clamp(p.trust-5);msg='El club rechaza renegociar ahora. La dirección deportiva no está convencida.'}}else if(kind==='market'){S.agent.market=true;p.rep=clamp(p.rep+6);p.focus=clamp(p.focus-4);msg='Tu agente comparte vídeos y datos con varios clubes. Ganarás visibilidad.'}else if(kind==='minutes'){S.agent.minutes=true;p.trust=clamp(p.trust+(Math.random()<.65?6:-5));p.focus=clamp(p.focus+3);msg='Conversación con el entrenador. '+(p.trust>=55?'Le gusta tu predisposición.':'Te pide paciencia y profesionalidad.')}note(msg);persist();render();notify(msg)}
function agent(){let p=S.player;S.agent=S.agent||{contract:false,market:false,minutes:false};return `${navigation()}<div class="card"><div class="eyebrow">Agencia de representación</div><h2 style="margin:8px 0">La carrera también se negocia.</h2><p class="muted" style="line-height:1.7;font-size:13px">Los contratos no son solo dinero. Tu nivel, los minutos y la reputación determinan el interés de otros clubes. Los traspasos se formalizan durante el mercado de verano, al terminar cada temporada.</p><div class="cols3" style="margin:15px 0">${statUI('Valor mercado',money(marketValue()))}${statUI('Sueldo semanal',money(p.wage))}${statUI('Saldo personal',money(p.balance))}</div><div class="grid" style="gap:11px">${[['contract','Renegociar salario','Solicitar una mejora de sueldo. Sin minutos ni rendimiento, puede salir mal.'],['market','Activar contactos','Tu agente llama a clubes y ojeadores. Aumenta visibilidad y ruido mediático.'],['minutes','Pedir reunión al entrenador','Plantear tu situación y pedir feedback sobre los minutos.']].map(([id,n,desc])=>`<button class="pick" onclick="Game.agent('${id}')" ${S.agent[id]?'disabled':''}><strong>${n} ${S.agent[id]?'✓':''}</strong><small>${desc}</small></button>`).join('')}</div><p class="micro" style="margin:13px 0 0">Puedes realizar cada gestión una vez por temporada. Tu salario se ingresa, descontados gastos básicos, después de cada partido.</p></div><div class="card" style="margin-top:16px"><h3>Rumores y contexto</h3><p class="muted" style="font-size:13px;line-height:1.7">${overall(p)>=75?'Tus actuaciones ya interesan a equipos de categorías importantes.':overall(p)>=67?'Los clubes siguen tu evolución. Un buen año puede abrir puertas.':'Todavía estás construyendo tu reputación. La constancia será decisiva.'}</p>${badge('Contrato '+p.contract+' años')} ${badge('Reputación '+Math.round(p.rep)+'/100')}</div>`}
function history(){let h=S.history||[],career=h.reduce((a,z)=>({apps:a.apps+z.played,goals:a.goals+z.goals,assists:a.assists+z.assists}),{apps:S.stats.apps,goals:S.stats.goals,assists:S.stats.assists});return `${navigation()}<div class="card"><div class="sectionhead"><h2>Una carrera por escribir</h2>${badge('Temporada '+S.seasonNo)}</div><div class="smallgrid">${statUI('Partidos',career.apps)}${statUI('Goles',career.goals)}${statUI('Asist.',career.assists)}${statUI('Campañas',S.seasonNo)}</div><hr class="divider">${h.length?h.slice().reverse().map(z=>`<div class="fixture"><div class="names"><strong style="font-size:15px">${z.year}/${z.year+1} · ${esc(z.club)}</strong><div class="micro">${DIVS[z.tier].name} · ${rankName(z.rank)} puesto · ${z.played} PJ · ${z.goals} G · ${z.assists} A · ${z.avg.toFixed(1)} media</div>${z.award?`<div style="margin-top:7px">${badge(esc(z.award),'green')}</div>`:''}</div></div>`).join(''):'<p class="empty">Todavía no has terminado ninguna temporada. Tu historia empieza aquí.</p>'}</div><div class="card" style="margin-top:16px"><h3>Sala de trofeos</h3>${S.awards?.length?S.awards.map(a=>`<div class="medal" style="margin:8px 0">★ ${esc(a.title)} · ${a.year}/${a.year+1}</div>`).join(''):'<p class="empty">Los títulos se ganan sobre el césped.</p>'}</div>`}
function matchHeader(m){let p=S.player,home=m.home?S.club.name:m.opp,away=m.home?m.opp:S.club.name,h=m.home?m.scoreUs:m.scoreThem,a=m.home?m.scoreThem:m.scoreUs;return `<div class="matchhead"><div class="eyebrow" style="margin-bottom:12px">${leagueLabel()} · Jornada ${S.round+1} · ${m.home?'En casa':'A domicilio'}</div><div class="scoreboard"><div><div class="teamname">${esc(home)}</div><small>${m.home?'Tu equipo':'Rival'}</small></div><div><div class="score">${h} <span style="color:#87b5a0">:</span> ${a}</div><div class="minute">${m.minute?m.minute+"'":'PREVIA'}</div></div><div><div class="teamname">${esc(away)}</div><small>${m.home?'Rival':'Tu equipo'}</small></div></div></div>`}
function matchScreen(){let u=upcoming(),p=S.player,m=S.match;if(!m){return `<div class="sectionhead"><div><div class="eyebrow">Día de partido · Jornada ${S.round+1}</div><h2 style="margin:6px 0">El día de la verdad</h2></div><button class="tinybtn" onclick="Game.back()">← Vestuario</button></div><div class="matchhead"><div class="eyebrow" style="margin-bottom:12px">${leagueLabel()}</div><div class="scoreboard"><div class="teamname">${esc(u.home?S.club.name:u.opp)}</div><div class="score" style="color:var(--accent)">VS</div><div class="teamname">${esc(u.home?u.opp:S.club.name)}</div></div><div class="micro" style="margin-top:14px">${u.home?(S.club.name==='CE Sabadell'?'Local · Nova Creu Alta':'Local · Estadio propio'):(u.opp==='CE Sabadell'?'Visitante · Nova Creu Alta':'Visitante · Estadio rival')}</div></div><div class="cols2" style="margin-top:16px"><div class="card"><div class="eyebrow">Tus condiciones</div><div class="statrow"><span>Posición</span><strong>${p.pos}</strong></div><div class="statrow"><span>Media</span><strong>${overall(p)}</strong></div><div class="statrow"><span>Forma física</span><strong>${Math.round(p.fitness)}%</strong></div><div class="statrow"><span>Confianza</span><strong>${Math.round(p.trust)}/100</strong></div>${p.injured?'<div class="alert red">Estás lesionado y no podrás disputar el partido.</div>':''}${p.suspension?'<div class="alert warn">Estás sancionado y no puedes jugar este encuentro.</div>':''}</div><div class="card"><div class="eyebrow">Análisis del rival</div><h3 style="font-size:22px;margin:6px 0">${esc(u.opp)}</h3><div class="statrow"><span>Potencia rival</span><strong>${getClub(u.opp).power}</strong></div><div class="statrow"><span>Potencia de tu equipo</span><strong>${S.club.power}</strong></div><div class="statrow"><span>Contexto</span><strong>${getClub(u.opp).power>S.club.power+4?'Partido exigente':getClub(u.opp).power<S.club.power-4?'Favoritos':'Equilibrado'}</strong></div><p class="micro">Tu puesto depende del nivel, las últimas actuaciones, la condición física y la confianza del míster. El resultado también dependerá de tus compañeros.</p></div></div><div style="margin-top:16px" class="actions"><button class="btn" onclick="Game.startMatch()">Ver convocatoria y estrategia →</button><button class="btn ghost" onclick="Game.back()">Volver al vestuario</button></div></div>`}
let role=m.enter===0?'TITULAR':m.enter>0?'SUPLENTE':'NO CONVOCADO';let tacticOptions=[['calm','Control y orden','Menos riesgos, algo menos de peligro y desgaste.'],['balance','Equilibrado','Alternar seguridad y verticalidad.'],['attack','Atacar sin miedo','Más ocasiones, pero regalas espacios y fuerzas la máquina.']];return `<div class="sectionhead"><div><div class="eyebrow">Jornada ${S.round+1} · ${m.started?'En directo':'Túnel de vestuarios'}</div><h2 style="margin:5px 0">${m.started?'¡El partido está en juego!':'Últimas instrucciones'}</h2></div>${badge(role,m.enter===0?'green':m.enter>0?'yellow':'red')}</div>${matchHeader(m)}${!m.started?`<div class="card" style="margin-top:16px"><div class="sectionhead"><h3>Tu situación</h3>${badge(m.enter===0?'Sales de inicio':m.enter>0?'Entrarías sobre el '+m.enter+"'":'Te quedas en el banquillo',m.enter===-1?'red':'')}</div><p class="muted" style="font-size:13px;line-height:1.7">${m.enter===0?'El entrenador confía en ti desde el primer minuto. Es tu oportunidad.':m.enter>0?'No eres titular hoy. Te preparas por si el entrenador te da entrada durante la segunda mitad.':p.suspension?'La sanción te impide disputar el encuentro.':p.injured?'Sigues con el parte médico abierto y no podrás jugar.':'Hoy el míster no te dará minutos. Podrás observar el encuentro y recuperar fuerzas.'}</p><div class="label" style="margin-top:18px">Plan personal para el partido</div><div class="cols3">${tacticOptions.map(([k,t,d])=>`<button class="pick ${m.tactics===k?'selected':''}" onclick="Game.tactic('${k}')"><strong>${esc(t)}</strong><small>${esc(d)}</small></button>`).join('')}</div><div class="actions" style="margin-top:18px"><button class="btn" onclick="Game.playMatch()">${m.enter<0?'Ver encuentro':'Jugar acciones'} →</button><button class="btn secondary" onclick="Game.quick()">Simular partido completo</button><button class="btn ghost" onclick="Game.back()">Volver</button></div></div>`:`<div class="ratings" style="margin-top:14px"><div class="rating"><b>${m.enter<0?'—':m.rating.toFixed(1)}</b><small>Nota</small></div><div class="rating"><b>${m.stats.goals}</b><small>Goles</small></div><div class="rating"><b>${m.stats.assists}</b><small>Asistencias</small></div><div class="rating"><b>${m.stats.saves||m.stats.tackles}</b><small>${p.pos==='POR'?'Paradas':'Recup.'}</small></div><div class="rating"><b>${Math.round(p.fitness)}%</b><small>Físico</small></div></div><div class="progress" style="margin-top:16px"><div style="width:${m.minute/90*100}%"></div></div>${m.step<m.scenes.length?`<div class="scene"><div class="eyebrow">Minuto ${m.scenes[m.step].minute} · Decisión ${m.step+1}/${m.scenes.length}</div><h3 class="decision">${esc(m.scenes[m.step].scene.title)}</h3><p>${esc(m.scenes[m.step].scene.desc)}</p><div class="grid" style="gap:9px">${m.scenes[m.step].scene.opts.map(([title,skill,type,diff],i)=>`<button class="pick" onclick="Game.choice(${i})"><strong>${esc(title)}</strong><small>${esc(type==='safe'?'Opción más conservadora':diff>=.60?'Acción de alta dificultad':diff>=.40?'Riesgo intermedio':'Opción de menor riesgo')} · ${esc(ATTRS[skill]||'Concentración')}: ${Math.round(skill==='focus'?p.focus:p.attrs[skill]||50)}</small></button>`).join('')}</div></div>`:''}<div class="actions" style="margin:15px 0"><button class="btn secondary" onclick="Game.quick()">Simular resto del partido »</button></div><div class="card"><h3>Relato en vivo</h3><div class="matchlog">${m.events.slice().reverse().map(e=>`<div class="${e.highlight?'highlight':''}"><strong>${e.minute}'</strong>${esc(e.text)}</div>`).join('')}</div></div>`}`}
function postMatch(){let r=S.lastResult,m=S.match,p=S.player;if(!r||!m)return '';let outcome=r.us>r.them?'VICTORIA':r.us===r.them?'EMPATE':'DERROTA';return `<div class="eyebrow">Final · Jornada ${S.round+1}</div><div class="sectionhead"><h2 style="margin:6px 0">${outcome==='VICTORIA'?'Tres puntos para el equipo.':outcome==='EMPATE'?'Un punto más.':'Toca aprender y seguir.'}</h2>${badge(outcome,outcome==='VICTORIA'?'green':outcome==='DERROTA'?'red':'yellow')}</div>${matchHeader(m)}<div class="card" style="margin-top:15px"><div class="eyebrow">Actuación individual · ${esc(p.name)}</div><div class="smallgrid" style="margin-top:15px">${statUI('Nota',r.minutes?r.rating.toFixed(1):'—')}${statUI('Minutos',r.minutes)}${statUI('Goles',r.goals)}${statUI('Asist.',r.assists)}</div>${r.minutes===0?'<div class="alert warn" style="margin-top:14px">No has disputado minutos hoy. Tu futuro puesto dependerá de los entrenamientos, la confianza y las próximas convocatorias.</div>':r.rating>=8?'<div class="alert" style="margin-top:14px">Gran actuación. Tu nombre empezará a sonar en el vestuario y en las gradas.</div>':r.rating<5.7?'<div class="alert warn" style="margin-top:14px">Un día complicado. Tendrás que reaccionar y cuidar la confianza del entrenador.</div>':''}</div><div class="cols2" style="margin-top:16px"><div class="card"><h3>La zona mixta</h3><p class="muted" style="font-size:13px;line-height:1.6">La prensa te acerca un micrófono: «¿Cómo valoras el partido y tu situación?»</p>${S.pressAnswered?'<div class="alert">Ya has respondido. Tus palabras tendrán repercusión.</div>':`<div class="grid" style="gap:9px"><button class="pick" onclick="Game.press('team')"><strong>«Lo importante es el grupo»</strong><small>Confianza y química del vestuario</small></button><button class="pick" onclick="Game.press('bold')"><strong>«Puedo ser una estrella aquí»</strong><small>Más atención mediática, pero asumes presión</small></button><button class="pick" onclick="Game.press('honest')"><strong>«Tengo que mejorar detalles»</strong><small>Autocrítica y concentración</small></button><button class="pick" onclick="Game.press('silent')"><strong>No hacer declaraciones</strong><small>Evitas ruido mediático</small></button></div>`}</div><div class="card"><h3>El vestuario espera</h3><p class="muted" style="font-size:13px;line-height:1.7">Al pasar de jornada, se cobra el salario semanal y recuperas parte de tu condición. Los rivales también siguen sumando puntos.</p><div class="statrow"><span>Salario bruto semanal</span><strong>${money(p.wage)}</strong></div><div class="statrow"><span>Gastos de vida aproximados</span><strong>${money(S.stage==='academy'?Math.min(25,p.wage*.28):p.wage<1600?Math.min(110,p.wage*.27):p.wage*.14)}</strong></div><div class="statrow"><span>Saldo disponible</span><strong style="color:var(--accent)">${money(p.balance)}</strong></div><button class="btn block" style="margin-top:19px" onclick="Game.next()">${S.round+1>=S.schedule.length?'Terminar temporada y ver mercado':'Avanzar a la jornada '+(S.round+2)} →</button></div></div>`}
function seasonScreen(){let z=S.seasonSummary,p=S.player,st=sortedTable(),idx=S.accepted;return `<div class="eyebrow">Final de temporada · ${S.year}/${S.year+1}</div><div class="hero card" style="margin-top:10px"><div style="position:relative;z-index:1"><h1>${z.rank===1?'¡CAMPEONES!':z.promoted?'¡ASCENSO!':z.relegated?'Temporada dura.':'Un año más de fútbol.'}</h1><p class="bigmuted">${esc(S.club.name)} · ${DIVS[S.history.at(-1).tier].name}<br>Has terminado en ${rankName(z.rank)} posición con ${z.points} puntos.</p>${z.awards.map(a=>badge(esc(a),'green')).join(' ')}</div><div class="metric" style="z-index:1;position:relative"><strong style="font-size:41px">${z.rank}º</strong><span>Puesto final</span></div></div><div class="smallgrid" style="margin-top:15px">${statUI('Partidos',z.played)}${statUI('Goles',z.goals)}${statUI('Asist.',z.assists)}${statUI('Nota',z.avg?z.avg.toFixed(1):'—')}</div><div class="card" style="margin-top:16px"><div class="sectionhead"><div><div class="eyebrow">Mercado de verano</div><h2 style="margin:5px 0 0">Tu futuro está en juego</h2></div>${badge('Elegir destino')}</div><p class="muted" style="font-size:13px;line-height:1.6">Puedes quedarte y continuar tu historia o cambiar de club. Cada propuesta incluye categoría y salario. Tu decisión se aplicará al comenzar la nueva temporada.</p><div class="grid" style="gap:10px"><button class="pick ${idx===undefined?'selected':''}" onclick="Game.stay()"><strong>Seguir en ${esc(S.club.name)}</strong><small>${DIVS[S.club.tier].name} · Se revisará tu contrato actual (${money(p.wage)}/semana)</small></button>${S.offers.length?S.offers.map((o,i)=>`<button class="pick ${idx===i?'selected':''}" onclick="Game.offer(${i})"><strong>${esc(o.name)} ${badge(o.tier<S.club.tier?'Salto de nivel':'Oferta','green')}</strong><small>${DIVS[o.tier].name} · ${money(o.wage)}/semana · ${o.contract} años de contrato · Equipo nivel ${o.power}</small></button>`).join(''):'<p class="empty">No han llegado ofertas concretas este verano. Continúas en tu club.</p>'}</div><button class="btn block" style="margin-top:16px" onclick="Game.beginSeason()">Confirmar ${idx===undefined?'continuidad':'fichaje por '+esc(S.offers[idx]?.name||S.club.name)} y jugar ${S.year+1}/${S.year+2} →</button></div><div class="card" style="margin-top:16px"><h3>Clasificación final</h3>${leagueTable()}</div>`}
function setup(){return `<div class="setup"><div class="setuphero"><div class="eyebrow">Simulador de carrera · Solo HTML</div><h1 style="margin:12px 0">FUERA DE <span style="color:var(--accent)">GUIÓN.</span></h1><p class="muted">Desde la Nova Creu Alta hasta los grandes estadios. Crea un futbolista, decide cómo vive, entrénalo y juega las situaciones que pueden definir cada partido. No hay un guion fijo: las consecuencias cuentan.</p></div><div class="card setupcard"><div class="setupform"><div class="eyebrow">Capítulo 00 / Tu debut</div><h2 style="margin:9px 0 24px">¿Quién quieres ser?</h2><div class="fieldset"><div class="field"><label for="name">Nombre del jugador</label><input id="name" maxlength="28" placeholder="Ej.: Álex García" value=""></div><div class="field"><label for="age">Edad al debut</label><select id="age"><option value="17">17 años</option><option value="18" selected>18 años</option><option value="19">19 años</option><option value="20">20 años</option><option value="21">21 años</option><option value="22">22 años</option></select></div><div class="field"><label for="position">Posición</label><select id="position">${Object.entries(POSITIONS).map(([id,o])=>`<option value="${id}" ${id==='MCO'?'selected':''}>${o[0]}</option>`).join('')}</select></div><div class="field"><label for="foot">Pie dominante</label><select id="foot"><option>Diestro</option><option>Zurdo</option><option>Ambidiestro</option></select></div><div class="field"><label for="style">Perfil de juego</label><select id="style"><option value="equilibrado">Equilibrado</option><option value="tecnico">Técnico</option><option value="potente">Físico</option><option value="goleador">Finalizador</option><option value="tactico">Táctico</option></select></div><div class="field"><label for="difficulty">Dificultad</label><select id="difficulty"><option value="realista" selected>Realista · Exigente</option><option value="casual">Casual · Más oportunidades</option></select></div><div class="field" style="grid-column:1/-1"><label for="club">Primer club</label><select id="club">${['CE Sabadell','CD Castellón','Sporting de Gijón','RCD Mallorca','CD Tenerife','Celta Fortuna','Nàstic de Tarragona','CE Europa','Real Murcia','FC Cartagena','Real Zaragoza','FC Barcelona'].map(n=>`<option value="${esc(n)}">${esc(n)} · ${DIVS[CLUBS[n][0]].short}</option>`).join('')}</select><small>Base de datos de clubes de 2026/27. El Sabadell empieza en Segunda, recién ascendido.</small></div></div><button class="btn block" style="margin-top:24px;padding:16px" onclick="Game.create()">COMENZAR MI CARRERA →</button><p class="micro" style="margin:14px 0 0;line-height:1.6">42 jornadas en Segunda, 38 en Primera y Primera Federación; decisiones, fichajes y resultados simulados. El guardado es automático cuando el navegador lo permite.</p>${!STORE_OK?'<div class="alert warn" style="margin-top:12px">Este navegador no permite guardar automáticamente desde aquí. Puedes jugar igualmente, pero descarga copias de seguridad durante la carrera.</div>':''}</div><div class="setupvisual"><div class="jersey wrap"><span>10</span></div><div style="text-align:center;margin:30px 0 10px"><div class="eyebrow">Tu primera camiseta</div><h2 style="font-size:33px;margin:6px 0">Todo empieza aquí.</h2><p style="font-size:13px;color:#b6d1c2;line-height:1.7">Un club. Una oportunidad. Noventa minutos. Miles de futuros posibles.</p></div><div class="ratings" style="justify-content:center">${badge('⚽ PARTIDOS')}${badge('★ DECISIONES')}${badge('↗ ASCENSOS')} ${badge('2026/27')}</div></div></div></div>`}
function render(){const root=$('root');if(!root)return;if(!S){root.innerHTML=`<div class="app"><div class="top"><div class="brand"><span class="brandicon">F</span><div><div class="brandname">FUERA DE GUIÓN</div><div class="eyebrow">Career simulator</div></div></div><div class="topright">${store.getItem(SAVE_KEY)?'<button class="tinybtn" onclick="Game.resume()">↻ Continuar partida</button>':''}<button class="tinybtn" onclick="document.getElementById('importFile').click()">Importar partida</button></div></div>${setup()}<div class="footer">Base de clubes y categorías 2026/27. Partidos, calendario completo, progresión y fichajes ficticios.</div></div>`;return}let p=S.player;let inner=S.view==='hub'?(activeTab==='player'?profile():activeTab==='league'?leagueView():activeTab==='agent'?agent():activeTab==='history'?history():hub()):S.view==='match'?matchScreen():S.view==='post'?postMatch():S.view==='season'?seasonScreen():hub();root.innerHTML=`<div class="app"><div class="top"><div class="brand"><span class="brandicon">F</span><div><div class="brandname">FUERA DE GUIÓN</div><div class="eyebrow">${esc(S.club.name)} · ${S.year}/${S.year+1}</div></div></div><div class="topright"><span class="pill">${p.pos} · ${overall(p)} OVR</span><button class="tinybtn" title="Descargar copia de la carrera" onclick="Game.export()">↓ Guardar copia</button><button class="tinybtn" onclick="document.getElementById('importFile').click()">Importar</button><button class="tinybtn" onclick="Game.reset()">↻ Nueva</button></div></div>${S.view==='hub'?`<div class="layout"><main class="maincol">${inner}</main><aside class="sidecol">${playerStatus()}${clubSide()}${inboxUI()}</aside></div>`:`<div style="max-width:990px;margin:auto">${inner}</div>`}${!STORE_OK?'<div class="alert warn" style="margin:17px 0">El guardado local no está disponible en este visor. Usa «Guardar copia» para conservar tus avances.</div>':''}<div class="footer">FUERA DE GUIÓN v2.0 · Guardado local · Equipos 2026/27 · Partidos y carreras ficticios · Sin conexión.</div></div>`}
