const META={},YOUTH_COUNTRIES={};
for(const [key,entry] of Object.entries(LEAGUES)){
  const [country,label,tier,list]=entry;
  entry.teams=list.split('|');
  for(const [i,n] of entry.teams.entries()){
    let power=tier===1?Math.round(83-i*1.28+(i<2?5:0)):tier===2?Math.round(74-i*.9):Math.round(67-i*.5);
    // Conservar potencia española original donde tenga sentido; sin pretender exactitud de la plantilla.
    if(!CLUBS[n])CLUBS[n]=[tier,power,n.slice(0,3).toUpperCase()];
    META[n]={country,league:key,tier,power:CLUBS[n][1],youth:false};
    let u=n+' Sub-19';
    CLUBS[u]=[4,Math.round(clamp(60+(power-65)*.20+rand(-1,1),55,67)),n.slice(0,3).toUpperCase()+'U'];
    META[u]={country,league:'U_'+country,tier:4,power:CLUBS[u][1],youth:true,parent:n};
    if(!YOUTH_COUNTRIES[country])YOUTH_COUNTRIES[country]=[];
    YOUTH_COUNTRIES[country].push(u);
  }
}
function getClub(n){let c=CLUBS[n],m=META[n];return {name:n,power:c?.[1]||65,short:c?.[2]||n.slice(0,3).toUpperCase(),tier:c?.[0]||3,league:m?.league||'ES3',country:m?.country||'España',parent:m?.parent||null};}
function leagueLabel(c=S.club){return c.tier===4?`${c.country} · Liga juvenil Sub-19`:(LEAGUES[c.league]?`${c.country} · ${LEAGUES[c.league][1]}`:DIVS[c.tier]?.name||'Liga nacional')}
function clubClass(c){return c.tier===4?'CANTERA':c.tier===3?'TERCERA CATEGORÍA':c.tier===2?'SEGUNDA CATEGORÍA':'PRIMERA CATEGORÍA'}
function leagueClubs(tier,playerClub){let m=META[playerClub],key=S.club.league||m?.league,all=Object.keys(META).filter(n=>META[n].league===key);if(!all.includes(playerClub))all.unshift(playerClub);let size=tier===4?Math.min(12,Math.max(8,Math.floor(all.length/2)*2)):key==='ES2'?22:key==='ES1'?20:key==='ES3'?16:Math.min(16,Math.max(10,Math.floor(all.length/2)*2));let names=[playerClub,...all.filter(n=>n!==playerClub)].slice(0,size);if(names.length%2)names.pop();return names;}
function buildSchedule(names){let a=[...names],n=a.length,first=[];for(let r=0;r<n-1;r++){let games=[];for(let i=0;i<n/2;i++){let h=a[i],away=a[n-1-i];games.push(r%2===0?[h,away]:[away,h]);}first.push(games);a=[a[0],a[n-1],...a.slice(1,n-1)];}return first.concat(first.map(round=>round.map(([h,a])=>[a,h])));}
function newSeasonSchedule(){let names=leagueClubs(S.club.tier,S.club.name);S.schedule=buildSchedule(names);S.table=newTable(names);S.round=0;S.week={training:false,life:false};S.lastResult=null;S.offers=[];S.story=null;S.match=null;S.agent={contract:false,market:false,minutes:false};S.stats={apps:0,starts:0,minutes:0,goals:0,assists:0,saves:0,tackles:0,clean:0,yellow:0,red:0,ratings:[],motm:0};S.results=[];S.view='hub';activeTab='hub';makeWatchlist();}
function create(){
 let name=($('name')?.value||'').trim().slice(0,28)||'Álex García',age=Number($('age')?.value||17),pos=$('position')?.value||'MCO',foot=$('foot')?.value||'Diestro',difficulty=$('difficulty')?.value||'realista',style=$('style')?.value||'equilibrado';let base=DEFAULT[pos];let bonus={equilibrado:{},tecnico:{pase:4,regate:4,fisico:-4,ritmo:-2},potente:{fisico:5,ritmo:3,pase:-3,regate:-2},goleador:{tiro:5,pase:-3,defensa:-2},tactico:{defensa:4,pase:3,tiro:-2,ritmo:-2}}[style]||{};
 let attrs=Object.fromEntries(SKILLS.map((k,i)=>[k,clamp(base[i]-2+(bonus[k]||0)+rand(-4,3),8,88)]));
 S={version:3,stage:'draft',player:{name,age,pos,foot,style,attrs,potential:int(80,91),fitness:95,morale:68,focus:70,trust:42,chemistry:50,rep:3,balance:260,wage:0,injured:0,suspension:0,contract:1},club:{name:'Sin equipo',tier:4,power:60,league:'NONE',country:'—'},difficulty,year:2026,seasonNo:1,round:0,view:'draft',week:{training:false,life:false},story:null,match:null,inbox:[],history:[],results:[],awards:[],offers:[],watchlist:[],pressAnswered:false,draftRerolls:2};
 rerollAcademy(false);persist();render();
}
function rerollAcademy(redraw=true){if(!S||S.view!=='draft')return;if(redraw){if(!S.draftRerolls)return;S.draftRerolls--;}let tiers=[[86,99],[74,85],[62,73]],used=new Set(),offers=[];
 for(let group=0;group<3;group++){
  let candidates=Object.keys(META).filter(n=>META[n].youth&&!used.has(META[n].country)&&META[META[n].parent]?.power>=tiers[group][0]&&META[META[n].parent]?.power<=tiers[group][1]);
  if(!candidates.length)candidates=Object.keys(META).filter(n=>META[n].youth&&!used.has(META[n].country));
  let youth=pick(candidates),m=META[youth],senior=META[m.parent],scenarios=[['Gran escaparate','Presión alta, instalaciones de élite y minutos más difíciles'],['Proyecto de desarrollo','Equilibrio entre exigencia, formación y oportunidades'],['Ruta a primer equipo','Menor exposición, pero el salto podría llegar antes']];
  offers.push({name:youth,parent:m.parent,country:m.country,league:m.league,power:CLUBS[youth][1],tier:4,label:scenarios[group][0],description:scenarios[group][1],wage:group===0?int(45,90):group===1?int(35,80):int(20,65),group}); used.add(m.country);
 }
 S.academyOffers=offers;persist();if(redraw)render();
}
function draftScreen(){let p=S.player;return `<div class="setup"><div class="setuphero"><div class="eyebrow">CAPÍTULO 00 · PRIMERAS PRUEBAS</div><h1 style="margin:12px 0">Tres cartas. <span style="color:var(--accent)">Tu futuro.</span></h1><p class="muted">Tu representante ha conseguido <b>tres propuestas de cantera, de tres países distintos</b>. No fichas por el primer equipo: tendrás que demostrar que mereces una oportunidad.</p></div><div class="card" style="margin-bottom:16px"><div class="sectionhead"><div><div class="eyebrow">Informe del agente</div><h3 style="margin:6px 0">${esc(p.name)} · ${p.age} años · ${esc(POSITIONS[p.pos][0])}</h3></div>${badge('OVR '+overall(p),'green')}</div><p class="micro">A mayor prestigio del club, más competencia por cada minuto. Las categorías y calendarios son una simulación, no una reproducción exacta de 2026/27.</p></div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(240px,1fr))">${S.academyOffers.map((o,i)=>`<div class="card bright"><div class="eyebrow">OFERTA 0${i+1} · ${esc(o.country)} ${FLAGS[o.country]||'🌍'}</div><h2 style="font-size:25px;margin:11px 0">${esc(o.parent)}</h2>${badge('Cantera Sub-19','green')} ${badge('Equipo base: '+CLUBS[o.parent][1])}<p style="margin-top:17px;font-weight:900">${o.label}</p><p class="muted" style="font-size:13px;min-height:55px">${o.description}</p><div class="statrow"><span>Ayuda de formación / sem.</span><strong>${money(o.wage)}</strong></div><div class="statrow"><span>País / academia</span><strong>${esc(o.country)}</strong></div><button class="btn block" style="margin-top:18px" onclick="Game.join(${i})">Firmar con la cantera →</button></div>`).join('')}</div><div class="actions" style="justify-content:center;margin:20px 0"><button class="btn secondary" onclick="Game.reroll()" ${S.draftRerolls<=0?'disabled':''}>Buscar otras propuestas (${S.draftRerolls} disponibles)</button></div></div>`}
function joinAcademy(i){if(S?.view!=='draft'||!S.academyOffers?.[i])return;let o=S.academyOffers[i];S.club=getClub(o.name);S.club.parent=o.parent;S.stage='academy';S.player.wage=o.wage;S.player.contract=1;S.player.trust=48;S.player.chemistry=52;newSeasonSchedule();note('Has firmado por la cantera del '+o.parent+' ('+o.country+'). Primera meta: ganarte minutos y atraer ojeadores.');persist();render();notify('¡Empieza tu carrera en '+o.country+'!')}
function makeWatchlist(){let quality=overall(S.player),parent=S.club.parent,base=META[parent]?.power||S.club.power,candidates=Object.keys(META).filter(n=>!META[n].youth&&n!==S.club.name&&n!==parent&&META[n].power>=Math.max(58,quality+4)&&META[n].power<=quality+(S.stage==='academy'?24:21));
 if(S.stage==='academy'&&parent)candidates.unshift(parent);
 let usedCountries=new Set(),arr=[];for(let c of candidates.sort(()=>Math.random()-.5)){
  if(arr.length===4)break;let meta=META[c];if(!meta||usedCountries.has(meta.country)&&c!==parent)continue;usedCountries.add(meta.country);
  let pow=meta.power,delta=pow-quality,strict=clamp(Math.round(delta*.57),1,14),youth=S.stage==='academy';
  arr.push({name:c,country:meta.country,league:meta.league,power:pow,minutes:Math.round((youth?300:520)+strict*(youth?55:96)),avg:Number((6.5+strict*.068).toFixed(1)),ovr:Math.round(Math.max(58,pow-(youth?14:10))),contrib:Math.max(1,Math.round((strict+1)/3)),known:false});
 }
 if(arr.length<2){let extra=Object.keys(META).filter(x=>!META[x].youth&&META[x].power<=quality+20&&META[x].power>=quality&&x!==parent).sort(()=>Math.random()-.5);for(let c of extra.slice(0,3-arr.length)){let m=META[c];arr.push({name:c,country:m.country,league:m.league,power:m.power,minutes:420,avg:6.8,ovr:quality,contrib:2,known:false});}}
 S.watchlist=arr;
}
function objectiveProgress(o){let st=S.stats,p=S.player,contrib=st.goals+st.assists+(p.pos==='POR'?Math.floor(st.saves/7):['DFC','LI','LD','MCD'].includes(p.pos)?Math.floor(st.tackles/7):0);let actual=[st.minutes,avgRating(),overall(p),contrib],target=[o.minutes,o.avg,o.ovr,o.contrib];let values=actual.map((v,i)=>target[i]?clamp(v/target[i],0,1):1);return {actual,target,contrib,progress:values.reduce((a,b)=>a+b,0)/values.length,met:values.every(x=>x>=.999)};}
function scoutWidget(compact=false){if(!S.watchlist?.length)return '';return `<div class="card" style="margin-top:16px"><div class="sectionhead"><div><div class="eyebrow">RED DE OJEADORES · ${S.stage==='academy'?'CANTERA':'MERCADO'}</div><h3 style="margin:5px 0">Clubes que siguen tu evolución</h3></div>${badge('Requisitos de fichaje','green')}</div><p class="micro">Cumplir los mínimos te hace elegible para recibir una propuesta. No significa que el fichaje sea automático: influyen los minutos, la reputación y el presupuesto del club.</p><div class="grid" style="gap:10px">${S.watchlist.slice(0,compact?2:4).map(o=>{let x=objectiveProgress(o);return `<div class="scout-item"><div class="sectionhead" style="margin-bottom:9px"><div><strong>${esc(o.name)}</strong><div class="micro">${FLAGS[o.country]||'🌍'} ${esc(o.country)} · ${esc(LEAGUES[o.league]?.[1]||'Liga nacional')}</div></div>${badge(x.met?'Requisitos cumplidos':Math.round(x.progress*100)+'%',x.met?'green':'')}</div>${bar(x.progress*100)}<div class="scout-metrics"><span>${S.stats.minutes}/${o.minutes} min</span><span>${avgRating().toFixed(1)}/${o.avg.toFixed(1)} nota</span><span>${overall(S.player)}/${o.ovr} OVR</span><span>${x.contrib}/${o.contrib} G+A/acciones</span></div></div>`}).join('')}</div>${compact?'<button class="btn secondary small" onclick="Game.tab(\'agent\')" style="margin-top:12px">Ver todos los ojeadores →</button>':''}</div>`}
function seasonGoal(){let p=S.player,N=S.schedule?.length||20,k=S.stage==='academy'?.55:1;return {minutes:Math.round(N*38*k),avg:S.stage==='academy'?6.7:6.65,goals:['DC','EI','ED'].includes(p.pos)?Math.ceil(N/(S.stage==='academy'?9:7)):0,assists:['MCO','MC','MCD'].includes(p.pos)?Math.ceil(N/(S.stage==='academy'?10:8)):0,saves:p.pos==='POR'?Math.ceil(N*(S.stage==='academy'?.45:.65)):0};}
function leagueRules(tier,size){if(S.stage==='academy')return {auto:0,playoff:[0,0],drop:0,desc:'Liga juvenil ficticia, doble vuelta. No hay ascensos automáticos: el salto depende de los ojeadores y la valoración del club.'};if(S.club.league==='ES1')return {auto:0,playoff:[0,0],drop:3,desc:'Campeón por puntos; los tres últimos descienden.'};if(S.club.league==='ES2')return {auto:2,playoff:[3,6],drop:4,desc:'Los dos primeros ascienden; 3.º a 6.º disputan playoff; cuatro últimos descienden.'};return {auto:0,playoff:[0,0],drop:2,desc:'Competición doméstica simplificada. Las plazas europeas y el formato real de ascensos no se simulan en todas las ligas.'};}
function seasonEnd(){let table=sortedTable(),rank=table.findIndex(t=>t.name===S.club.name)+1,stats=S.stats,avg=avgRating(),youth=S.stage==='academy';let promoted=false,relegated=false,playoffs=false,playoffResult='';
 if(!youth&&S.club.league==='ES2'){promoted=rank<=2;playoffs=rank>=3&&rank<=6;relegated=rank>=table.length-3;}
 else if(!youth&&S.club.league==='ES3'){promoted=rank===1;playoffs=rank>=2&&rank<=5;}
 else if(!youth&&S.club.league==='ES1'){relegated=rank>=table.length-2;}
 if(playoffs){promoted=Math.random()<clamp(.22+(avg-6.6)*.07,.12,.56);playoffResult=promoted?'¡Tu equipo gana el playoff!':'El equipo cae eliminado en el playoff.';note(playoffResult)}
 let awards=[];if(avg>=8&&stats.apps>=5)awards.push('Once ideal de la temporada');if(rank===1)awards.push(youth?'Campeón juvenil':'Campeón de liga');if(promoted)awards.push('Ascenso de categoría');if(seasonGoalStatus().every(([nm,v,target])=>v>=target)){awards.push('Objetivos deportivos cumplidos');S.player.rep=clamp(S.player.rep+7);S.player.balance+=Math.round(S.player.wage*2);note('¡Objetivos personales cumplidos! Reputación y prima de temporada.');}
 S.awards.push(...awards.map(a=>({year:S.year,title:a})));S.history.push({year:S.year,club:S.club.name,tier:S.club.tier,league:leagueLabel(),rank,played:stats.apps,goals:stats.goals,assists:stats.assists,avg:Number(avg.toFixed(2)),award:awards.join(', '),promoted,relegated});S.seasonSummary={rank,played:stats.apps,goals:stats.goals,assists:stats.assists,avg,minutes:stats.minutes,position:youth?'temporada juvenil':promoted?'ascenso':relegated?'descenso':'permanencia',promoted,relegated,awards,points:table[rank-1].pts,playoffResult,youth};
 if(!youth&&(promoted||relegated)&&S.club.country==='España'){
 let next=S.club.tier+(promoted?-1:1),key='ES'+next;if(LEAGUES[key]){S.club.tier=next;S.club.league=key;S.club.power=clamp(S.club.power+(promoted?3:-3),54,95);note(promoted?'¡Ascenso! Próxima temporada: '+LEAGUES[key][1]:'Descenso a '+LEAGUES[key][1]);}}
 S.offers=generateOffers();S.view='season';persist();render();}
function generateOffers(){let p=S.player,ov=overall(p),avg=avgRating(),youth=S.stage==='academy',out=[],taken=new Set([S.club.name]);
 for(let o of S.watchlist||[]){let progress=objectiveProgress(o);if(!progress.met)continue;let interest=clamp(.36+(avg-7)*.12+p.rep*.005+(youth?.06:0),.18,.86);if(Math.random()>interest)continue;let c=getClub(o.name);out.push({name:c.name,tier:c.tier,power:c.power,league:c.league,country:c.country,wage:offerWage(c.power,ov),contract:int(2,4),role:roleFor(c.power,ov),reason:'Has cumplido los objetivos del ojeador'});taken.add(c.name);}
 // La trayectoria puede abrir puertas inesperadas, pero nunca ofertas de gigantes sin méritos.
 let all=Object.keys(META).filter(n=>!META[n].youth&&!taken.has(n)&&META[n].power<=ov+(youth?11:13)&&META[n].power>=Math.max(58,ov-11));
 let performance=clamp((avg-6.7)*.42+(p.rep-6)*.006+(S.stats.minutes/(S.schedule.length*90))*.25,0,.85);
 let extras=(Math.random()<performance?1:0)+(Math.random()<performance*.35?1:0);
 for(let n of all.sort(()=>Math.random()-.5).slice(0,Math.min(4,extras*3))){if(out.length>=4)break;if(Math.random()>performance+.20)continue;let c=getClub(n);out.push({name:n,tier:c.tier,power:c.power,league:c.league,country:c.country,wage:offerWage(c.power,ov),contract:int(1,3),role:roleFor(c.power,ov),reason:'Interés por tus estadísticas y proyección'});taken.add(n);}
 if(youth){let parent=S.club.parent,mp=META[parent];if(mp&&!taken.has(parent)){
 // Ascender a un club de élite desde juvenil es raro: hay que sobresalir.
 let req=clamp((mp.power-ov)/5,0,4);if(avg>=7.1+req*.24&&S.stats.minutes>=420+req*180&&ov>=mp.power-16){let c=getClub(parent);out.unshift({name:parent,tier:c.tier,power:c.power,league:c.league,country:c.country,wage:offerWage(c.power,ov),contract:3,role:'Promesa / equipo B',reason:'Tu club te ofrece contrato profesional'});}}
 if(p.age>=19&&!out.length){let low=Object.keys(META).filter(n=>!META[n].youth&&META[n].power<=ov+6&&META[n].power>=ov-12).sort(()=>Math.random()-.5)[0];if(low){let c=getClub(low);out.push({name:low,tier:c.tier,power:c.power,league:c.league,country:c.country,wage:offerWage(c.power,ov),contract:1,role:'Prueba / rotación',reason:'Contrato de oportunidad tras salir del juvenil'});}}
 }
 return out.filter((o,i,a)=>a.findIndex(x=>x.name===o.name)===i).slice(0,5);
}
function offerWage(power,ov){return Math.round(clamp(150+(ov-55)*95+(power-55)*48,170,38000)*rand(.87,1.16)/10)*10;}
function roleFor(pow,ov){return ov>=pow+4?'Titular previsto':ov>=pow-3?'Rotación':'Promesa / revulsivo';}
function beginSeason(){if(S.view!=='season')return;let p=S.player,old=S.club.name,youth=S.stage==='academy',idx=S.accepted;
 if(idx!==undefined&&S.offers[idx]){let o=S.offers[idx];S.club=getClub(o.name);S.club.power=o.power;S.stage='senior';p.wage=o.wage;p.contract=o.contract;p.trust=o.role==='Titular previsto'?62:o.role==='Rotación'?49:35;note('¡Nuevo contrato! '+o.name+' ('+o.country+'). '+o.role+'. '+money(o.wage)+'/semana.');}
 else if(youth){if(p.age>=19){let parent=S.club.parent,m=META[parent];if(m&&overall(p)>=m.power-13&&avgRating()>=7.1){S.club=getClub(parent);S.stage='senior';p.wage=offerWage(S.club.power,overall(p));note('El club te integra en dinámica profesional, pero tendrás que pelear cada convocatoria.');}else{let mid=Object.keys(META).filter(n=>!META[n].youth&&META[n].power<=overall(p)+5&&META[n].power>=overall(p)-12).sort(()=>Math.random()-.5)[0];if(mid){S.club=getClub(mid);S.stage='senior';p.wage=offerWage(S.club.power,overall(p));note('Termina tu etapa juvenil: una prueba te da contrato de un año en '+mid+'.');}else{p.wage=80;note('Una última temporada de formación.');}}}else{p.wage=Math.round(p.wage*1.08);note('Renuevas por una temporada más en la cantera de '+S.club.parent+'.');}}
 else{p.contract--;p.wage=Math.round(p.wage*(1+(S.seasonSummary.avg>=7.2?.11:.03)));if(p.contract<=0)p.contract=1;note('Continúas en '+S.club.name+' con nuevas metas.');}
 p.age++;p.fitness=clamp(p.fitness+30);p.morale=clamp(p.morale+10);p.focus=clamp(p.focus+8);p.injured=0;p.suspension=0;S.year++;S.seasonNo++;S.accepted=undefined;newSeasonSchedule();note('Nueva temporada '+S.year+'/'+(S.year+1)+'. '+(old!==S.club.name?'Adaptación a otra ciudad y nuevo vestuario.':'Una oportunidad más para crecer.'));persist();render();notify('¡Nueva temporada!');}
function nextWeek(){if(S.view!=='post')return;S.round++;let p=S.player;let overhead=S.stage==='academy'?Math.min(25,p.wage*.28):p.wage<1600?Math.min(110,p.wage*.27):p.wage*.14;p.balance+=p.wage-overhead;p.fitness=clamp(p.fitness+rand(17,24)+(S.difficulty==='casual'?4:0));p.morale=clamp(p.morale+rand(-2,2));p.focus=clamp(p.focus+rand(-1,2));if(p.injured>0){p.injured--;if(p.injured===0)note('Parte médico: recibes el alta competitiva.')}S.match=null;S.week={training:false,life:false};if(S.round>=S.schedule.length){seasonEnd();return;}if(S.round%5===0){for(let o of S.watchlist||[]){if(!o.known&&objectiveProgress(o).progress>.72){o.known=true;note('Ojeadores de '+o.name+' destacan tu progresión. Mantén los resultados.');}}}
 if((S.round%3===0||Math.random()<.19)&&!S.story)S.story=pick(STORIES).id;S.view='hub';activeTab='hub';persist();render();}
function setup(){return `<div class="setup"><div class="setuphero"><div class="eyebrow">CARRERA DE FUTBOLISTA · MUNDO ABIERTO</div><h1 style="margin:12px 0">FUERA DE <span style="color:var(--accent)">GUIÓN 4.</span></h1><p class="muted">No empiezas siendo una estrella. Eres una promesa de barrio buscando una oportunidad en el fútbol mundial. Tu agente te conseguirá tres pruebas, y tendrás que elegir dónde crecer.</p></div><div class="card setupcard"><div class="setupform"><div class="eyebrow">CAPÍTULO 00 / FÚTBOL BASE</div><h2 style="margin:9px 0 24px">Crea tu futbolista</h2><div class="fieldset"><div class="field"><label>Nombre</label><input id="name" maxlength="28" placeholder="Ej.: Álex García"></div><div class="field"><label>Edad</label><select id="age"><option value="16">16 años</option><option value="17" selected>17 años</option><option value="18">18 años</option></select></div><div class="field"><label>Posición</label><select id="position">${Object.entries(POSITIONS).map(([id,o])=>`<option value="${id}" ${id==='MCO'?'selected':''}>${o[0]}</option>`).join('')}</select></div><div class="field"><label>Pie dominante</label><select id="foot"><option>Diestro</option><option>Zurdo</option><option>Ambidiestro</option></select></div><div class="field"><label>Perfil</label><select id="style"><option value="equilibrado">Equilibrado</option><option value="tecnico">Técnico</option><option value="potente">Físico</option><option value="goleador">Goleador</option><option value="tactico">Táctico</option></select></div><div class="field"><label>Dificultad</label><select id="difficulty"><option value="realista" selected>Realista</option><option value="casual">Casual</option></select></div></div><button class="btn block" style="margin-top:24px;padding:16px" onclick="Game.create()">VER MIS TRES OFERTAS DE CANTERA →</button><p class="micro" style="margin-top:14px;line-height:1.6">33 países, clubes reales y competiciones simuladas. El calendario se comprime por diversión. Guardado local y exportación de partida.</p>${!STORE_OK?'<div class="alert warn">Tu navegador no admite el guardado automático desde este archivo; utiliza «Guardar copia» regularmente.</div>':''}</div><div class="setupvisual"><div class="jersey wrap"><span>17</span></div><div style="text-align:center;margin-top:30px"><div class="eyebrow">PRIMER CONTRATO</div><h2>Tu nombre aún no suena.</h2><p style="color:#b6d1c2;font-size:13px;line-height:1.7">España, Brasil, Dinamarca, Alemania, Japón, Argentina... La primera oportunidad puede llevarte a cualquier lugar.</p></div><div class="ratings" style="justify-content:center">${badge('🌍 33 PAÍSES')}${badge('⚽ CANTERAS')}${badge('📈 OJEADORES')}</div></div></div></div>`}
function hub(){return hubLegacy()+scoutWidget(true)}
function agent(){let p=S.player;return `${navigation()}<div class="card"><div class="eyebrow">REPRESENTANTE Y OJEADORES</div><h2 style="margin:8px 0">Nadie regala un fichaje.</h2><p class="muted" style="font-size:13px;line-height:1.7">Actualmente compites en <strong>${esc(leagueLabel())}</strong>. Los clubes te observan por nivel, nota media, minutos y contribución. Cumplir los objetivos no garantiza una oferta. Pueden llegar propuestas inesperadas si sobresales.</p><div class="cols3" style="margin:16px 0">${statUI('Valor estimado',money(marketValue()))}${statUI('Sueldo / semana',money(p.wage))}${statUI('Reputación',Math.round(p.rep)+'/100')}</div><div class="grid" style="gap:10px">${[['contract','Negociar contrato','Una petición precipitada puede perjudicar la relación con el club.'],['market','Enviar vídeos a ojeadores','Más visibilidad, pero también mayor presión.'],['minutes','Reunirme con el entrenador','Buscar minutos y recibir indicaciones para progresar.']].map(([id,n,desc])=>`<button class="pick" onclick="Game.agent('${id}')" ${S.agent?.[id]?'disabled':''}><strong>${n} ${S.agent?.[id]?'✓':''}</strong><small>${desc}</small></button>`).join('')}</div></div>${scoutWidget(false)}<div class="card" style="margin-top:16px"><h3>Ruta de carrera</h3><p class="muted" style="font-size:13px;line-height:1.7">${S.stage==='academy'?'Primero compites con el Sub-19. Puedes renovar tu formación, ascender al primer equipo si destacas o fichar por otro club que te siga.':'Ya eres profesional. Puedes quedarte, competir por tu puesto, o aceptar ofertas de otros países si te las ganas.'}</p></div>`;}
function leagueView(){return leagueViewLegacy().replace(DIVS[S.club.tier].name,leagueLabel());}
function leagueRulesSafe(){return S.stage==='academy'?{auto:0,playoff:[0,0],drop:0}:leagueRules(S.club.tier,Object.keys(S.table).length)}
function leagueTable(){let rank=sortedTable(),youth=S.stage==='academy';return `<div style="overflow-x:auto"><table class="league"><thead><tr><th style="text-align:left">#</th><th style="text-align:left">Club</th><th>PJ</th><th>G</th><th>E</th><th>P</th><th>GF</th><th>GC</th><th>DG</th><th>Pts</th></tr></thead><tbody>${rank.map((x,i)=>`<tr class="${x.name===S.club.name?'you':''} ${!youth&&i===0?'promo':''}"><td>${i+1}</td><td>${esc(x.name)}</td><td>${x.p}</td><td>${x.w}</td><td>${x.d}</td><td>${x.l}</td><td>${x.gf}</td><td>${x.ga}</td><td>${x.gf-x.ga}</td><td><strong>${x.pts}</strong></td></tr>`).join('')}</tbody></table></div>`;}
function clubSide(){let cur=upcoming(),rank=S.table?sortedTable().findIndex(x=>x.name===S.club.name)+1:0;return `<div class="card"><div class="eyebrow">${S.stage==='academy'?'TU ACADEMIA':'TU CLUB PROFESIONAL'}</div><h3 style="font-size:21px;margin:7px 0 4px">${esc(S.club.name)}</h3><p class="muted" style="font-size:12px">${FLAGS[S.club.country]||'🌍'} ${esc(leagueLabel())} · ${S.year}/${S.year+1}</p><div class="statrow"><span>Nivel del equipo</span><strong>${S.club.power}</strong></div><div class="statrow"><span>Posición</span><strong>${S.round?rank+'º':'—'}</strong></div><div class="statrow"><span>Siguiente rival</span><strong>${esc(cur?.opp||'—')}</strong></div></div>`}
function marketValue(){let p=S.player,ov=overall(p);return Math.round((S.stage==='academy'?2500:23000)*Math.pow(1.16,ov-57)*(1+p.rep*.012)/1000)*1000;}
function seasonScreen(){let z=S.seasonSummary,p=S.player,idx=S.accepted,youth=z.youth;return `<div class="eyebrow">FIN DE TEMPORADA · ${S.year}/${S.year+1} · ${esc(leagueLabel())}</div><div class="hero card" style="margin-top:10px"><div><h1>${z.rank===1?'¡Campeones!':youth?'Tu primer año deja huella.':z.promoted?'¡Ascenso conseguido!':'Un año más de fútbol.'}</h1><p class="bigmuted">${esc(S.club.name)} · Puesto ${z.rank}º · ${z.points} puntos</p>${z.awards.map(a=>badge(esc(a),'green')).join(' ')}</div><div class="metric"><strong>${z.rank}º</strong><span>Posición final</span></div></div><div class="smallgrid" style="margin-top:15px">${statUI('Partidos',z.played)}${statUI('Goles',z.goals)}${statUI('Asist.',z.assists)}${statUI('Nota',z.avg.toFixed(1))}</div><div class="card" style="margin-top:16px"><div class="eyebrow">MERCADO DE VERANO</div><h2 style="margin:7px 0 12px">¿Quién apuesta por ti?</h2><p class="muted" style="line-height:1.7;font-size:13px">${youth?'Esta es tu primera gran decisión. Si no aceptas ningún contrato, puedes continuar formándote (o buscar una salida de oportunidad si ya tienes edad de sénior).':'Puedes continuar compitiendo o cambiar de equipo y de país.'} Las propuestas dependen de tu rendimiento y nivel.</p><div class="grid" style="gap:10px"><button class="pick ${idx===undefined?'selected':''}" onclick="Game.stay()"><strong>${youth?'Quedarme y seguir desarrollándome':'Seguir en '+esc(S.club.name)}</strong><small>${youth?'El club estudiará la siguiente etapa de tu formación':'Continúas tu contrato actual y peleas por minutos'}</small></button>${S.offers.length?S.offers.map((o,i)=>`<button class="pick ${idx===i?'selected':''}" onclick="Game.offer(${i})"><strong>${FLAGS[o.country]||'🌍'} ${esc(o.name)} ${badge(o.role,'green')}</strong><small>${esc(o.country)} · ${esc(LEAGUES[o.league]?.[1]||'Liga nacional')} · ${money(o.wage)}/semana · ${o.contract} años</small><small style="color:var(--accent2)">${esc(o.reason)}</small></button>`).join(''):'<div class="alert warn">Ningún equipo ha presentado una oferta en firme. Tus estadísticas no han despertado suficiente interés esta vez.</div>'}</div><button class="btn block" style="margin-top:16px" onclick="Game.beginSeason()">Confirmar decisión y continuar carrera →</button></div><div class="card" style="margin-top:16px"><h3>Clasificación final</h3>${leagueTable()}</div>`}
function history(){let h=S.history||[],career=h.reduce((a,z)=>({apps:a.apps+z.played,goals:a.goals+z.goals,assists:a.assists+z.assists}),{apps:S.stats.apps,goals:S.stats.goals,assists:S.stats.assists});return `${navigation()}<div class="card"><div class="sectionhead"><h2>Tu trayectoria</h2>${badge('Temporada '+S.seasonNo)}</div><div class="smallgrid">${statUI('Partidos',career.apps)}${statUI('Goles',career.goals)}${statUI('Asist.',career.assists)}${statUI('Países',new Set([...h.map(z=>(META[z.club]?.country||'España')),S.club.country]).size)}</div><hr class="divider">${h.length?h.slice().reverse().map(z=>`<div class="fixture"><div class="names"><strong>${z.year}/${z.year+1} · ${esc(z.club)}</strong><div class="micro">${esc(z.league||'Liga nacional')} · ${z.rank}º · ${z.played} PJ · ${z.goals} G · ${z.assists} A · ${z.avg.toFixed(1)} de nota</div></div></div>`).join(''):'<p class="empty">Aún no hay temporadas completas.</p>'}</div><div class="card" style="margin-top:16px"><h3>Premios</h3>${S.awards?.length?S.awards.map(a=>`<div class="medal">★ ${esc(a.title)} · ${a.year}/${a.year+1}</div>`).join(''):'<p class="empty">Todo está por conseguir.</p>'}</div>`}
function render(){let root=$('root');if(!root)return;if(!S){root.innerHTML=`<div class="app"><div class="top"><div class="brand"><span class="brandicon">F</span><div><div class="brandname">FUERA DE GUIÓN</div><div class="eyebrow">Simulador de carrera · v3.0</div></div></div><div class="topright">${store.getItem(SAVE_KEY)?'<button class="tinybtn" onclick="Game.resume()">↻ Continuar</button>':''}<button class="tinybtn" onclick="document.getElementById('importFile').click()">Importar partida</button></div></div>${setup()}<div class="footer">Universo de ficción con nombres de clubes reales · Sin conexión · Archivo único HTML.</div></div>`;return;}
 let p=S.player;if(S.view==='draft'){root.innerHTML=`<div class="app"><div class="top"><div class="brand"><span class="brandicon">F</span><div class="brandname">FUERA DE GUIÓN</div></div><button class="tinybtn" onclick="Game.reset()">Nueva carrera</button></div>${draftScreen()}</div>`;return;}
 let inner=S.view==='hub'?(activeTab==='player'?profile():activeTab==='league'?leagueView():activeTab==='agent'?agent():activeTab==='history'?history():hub()):S.view==='match'?matchScreen():S.view==='post'?postMatch():S.view==='season'?seasonScreen():hub();
 root.innerHTML=`<div class="app"><div class="top"><div class="brand"><span class="brandicon">F</span><div><div class="brandname">FUERA DE GUIÓN</div><div class="eyebrow">${esc(S.club.name)} · ${S.year}/${S.year+1}</div></div></div><div class="topright"><span class="pill">${p.pos} · ${overall(p)} OVR</span><button class="tinybtn" onclick="Game.export()">↓ Guardar copia</button><button class="tinybtn" onclick="document.getElementById('importFile').click()">Importar</button><button class="tinybtn" onclick="Game.reset()">↻ Nueva</button></div></div>${S.view==='hub'?`<div class="layout"><main class="maincol">${inner}</main><aside class="sidecol">${playerStatus()}${clubSide()}${inboxUI()}</aside></div>`:`<div style="max-width:990px;margin:auto">${inner}</div>`}${!STORE_OK?'<div class="alert warn" style="margin:17px 0">El guardado local no está disponible en este visor. Descarga una copia de tu carrera.</div>':''}<div class="footer">FUERA DE GUIÓN 3 · +30 países · cantera a primer equipo · temporadas ficticias · sin conexión.</div></div>`;}
function resume(){try{let v=JSON.parse(store.getItem(SAVE_KEY));if(!v||!v.player||v.version!==3)throw Error('Datos incompatibles');S=v;activeTab='hub';render();notify('Partida cargada.')}catch(e){S=null;render();notify('No se pudo cargar la partida.');}}
function importGame(){let file=$('importFile').files[0];if(!file)return;let reader=new FileReader();reader.onload=()=>{try{let s=JSON.parse(reader.result);if(!s?.player?.attrs||s.version!==3)throw Error('Archivo incompatible');S=s;activeTab='hub';persist();render();notify('Carrera restaurada.')}catch(e){alert('No se pudo importar la partida: '+e.message)} };reader.readAsText(file);}

window.Game={join:joinAcademy,reroll:rerollAcademy,create,train,life,story:storyChoice,tab:switchTab,matchPre,startMatch,tactic,playMatch,choice:resolveChoice,quick:quickMatch,press,next:nextWeek,offer:acceptOffer,stay:()=>{S.accepted=undefined;persist();render()},beginSeason,agent:agentAction,back:()=>{if(S.match?.started){notify('No puedes abandonar un partido en marcha.');return}S.view='hub';S.match=null;persist();render()},export:exportGame,reset,resume};
