const V4_EVENT_STYLE=[
 ['En un momento de máxima exigencia,','El cuerpo técnico observa cada detalle.'],['En una semana en que te cuesta entrar en el once,','Tu respuesta puede influir en la confianza del míster.'],['Después de una actuación destacada,','Ahora todos esperan más de ti.'],['Con varios compañeros buscando su sitio,','El ambiente está competitivo.'],['En plena lucha por los objetivos,','El grupo necesita respuestas.'],['Con un calendario cargado,','La recuperación cobra especial importancia.'],['Cuando los rumores de mercado crecen,','Es fácil perder la concentración.'],['Tras una charla con el capitán,','Las relaciones del vestuario importan.'],['Durante tu adaptación en el extranjero,','Todo cuenta también fuera del césped.'],['En una jornada aparentemente tranquila,','Hasta las decisiones pequeñas dejan huella.']
];
const V4_WX=[['Soleado','Buen césped y condiciones estables.'],['Lluvia','El balón corre y los controles se complican.'],['Viento','Los envíos largos son menos precisos.'],['Frío','Las piernas necesitan entrar bien en calor.'],['Calor','La gestión de energía será decisiva.']];
function v4Init(){if(!S)return;if(!S.day||typeof S.day.index!=='number')S.day={index:0,events:{},answers:{},skipped:{},weekKey:null};let weekKey=`${S.year}-${S.seasonNo}-${S.round}`;if(S.day.weekKey!==weekKey){S.day={index:0,events:{},answers:{},skipped:{},weekKey};}if(!S.eventHistory)S.eventHistory=[];if(!S.matchHistory)S.matchHistory=[];if(!S.week)S.week={training:false,life:false};}
function v4Token(t){return t.replace(/\{club\}/g,S.club.name).replace(/\{country\}/g,S.club.country||'tu país').replace(/\{rival\}/g,upcoming()?.opp||'el próximo rival').replace(/\{jugador\}/g,S.player.name);}
function v4EventFor(day){v4Init();let key=day===0?'training':'life';if(S.day.events[key])return S.day.events[key];const pool=key==='training'?V4_TRAIN_EVENTS:V4_LIFE_EVENTS;let recent=new Set(S.eventHistory.slice(-Math.min(pool.length-1,26)));let possible=pool.map((event,i)=>({event,i,key:key+i})).filter(x=>!recent.has(x.key));if(key==='training'&&S.stage!=='academy')possible=possible.filter(x=>x.i!==4&&x.i!==22);if(key==='training'&&S.stage!=='academy')possible=possible.filter(x=>x.i!==4&&x.i!==22);let v=pick(possible.length?possible:pool.map((event,i)=>({event,i,key:key+i})));let context=S.round===0?'Es tu primera semana en este club.':S.player.fitness<46?'Llegas a esta situación con las piernas cargadas.':S.lastResult?.rating>=8?'Tus últimas actuaciones han elevado las expectativas.':S.lastResult?.rating>0&&S.lastResult.rating<5.9?'Tu rendimiento anterior dejó dudas y buscas reaccionar.':S.player.trust<40?'El cuerpo técnico está pendiente de tu actitud.':'Lo que elijas influirá en tu relación con el equipo.';let item={id:v.key,title:v.event[0],text:v4Token(`${v.event[1]} ${context}`),choices:v.event[2]};S.day.events[key]=item;return item;}
function v4EventChoice(kind,i){v4Init();if(S.view!=='hub'||S.day.index!==(kind==='training'?0:1)||S.day.answers[kind]!==undefined)return;let ev=v4EventFor(S.day.index);let opt=ev.choices[i];if(!opt)return;let moneyCost=opt[1].money||0;if(moneyCost<0&&S.player.balance<Math.abs(moneyCost)){notify('No tienes suficiente dinero.');return}mutate(opt[1]);S.day.answers[kind]=i;S.eventHistory.push(ev.id);S.eventHistory=S.eventHistory.slice(-130);note(`${ev.title}: ${opt[2]}`);persist();render();notify(opt[2]);}
function v4DayNext(skip){v4Init();if(S.view!=='hub')return;let day=S.day.index;if(day>=2)return;
 if(day===0){if(!S.week.training){if(!skip){notify('Elige entrenamiento o pulsa Descansar y continuar.');return}S.week.training=true;S.day.skipped.training=true;mutate({fitness:9,trust:-1});note('Has descansado en lugar de realizar el entrenamiento planificado.')}if(S.day.answers.training===undefined){if(!skip){notify('Resuelve el evento de entrenamiento o continúa sin intervenir.');return}S.day.answers.training=-1;note('No intervienes en la situación del campo de entrenamiento.')}S.day.index=1;v4EventFor(1);}
 else if(day===1){if(!S.week.life){if(!skip){notify('Elige un plan personal o usa Continuar sin actividad.');return}S.week.life=true;S.day.skipped.life=true;mutate({fitness:5,focus:2});}if(S.day.answers.life===undefined){if(!skip){notify('Resuelve el evento de vida personal o continúa sin intervenir.');return}S.day.answers.life=-1;note('Decides no intervenir en los asuntos fuera del campo.')}S.day.index=2;}
 activeTab=day===0?'life':'match';S.uiFocus='plan';persist();render();}
function v4Train(id){v4Init();if(S.view!=='hub'||S.day.index!==0){notify('El entrenamiento se realiza en su día correspondiente.');return}let ret=_v4Original.train(id);if(S.week.training){S.uiFocus='event';render()}return ret}
function v4Life(id){v4Init();if(S.view!=='hub'||S.day.index!==1){notify('Las actividades personales van en su jornada.');return}let ret=_v4Original.life(id);if(S.week.life){S.uiFocus='event';render()}return ret}
function v4Panel(k){if(!S)return;S.uiFocus=k;render()}
function v4Panel(k){if(!S)return;S.uiFocus=k;render()}
function v4OpenPhase(i){v4Init();if(i<0||i>2)return;if(i===2&&S.day.index!==2){notify('Primero prepara la semana: entrenamiento y vida personal.');return}if(i===2){matchPre();return}S.uiFocus=i===0?'plan':'plan';activeTab=i===0?'training':'life';S.view='hub';render();}
function v4BackHome(){if(S.view==='match'&&S.match?.started){notify('Termina el encuentro para salir.');return}S.view='hub';S.match=null;activeTab='hub';persist();render();}
function v4MatchContext(s,m){let weather=m.weather?.[0]||'Soleado';let extra=weather==='Lluvia'?'El césped está resbaladizo.':weather==='Viento'?'El viento altera la trayectoria del balón.':weather==='Calor'?'El calor aumenta el desgaste.':weather==='Frío'?'El frío dificulta los primeros apoyos.':'';let score=m.scoreUs-m.scoreThem;let impulse=s.minute>=72?(score<0?'Vais por detrás y el reloj aprieta.':score>0?'Vuestra ventaja exige inteligencia.':'El empate hace que cada detalle sea decisivo.'):(score<0?'Necesitáis recuperar terreno.':score>0?'Jugáis con la ventaja, sin relajarse.':'El encuentro sigue muy abierto.');return `${s.scene.desc} ${extra} ${impulse}`}
function v4Role(){let pos=S.player.pos;return pos==='POR'?'POR':['DFC','LI','LD'].includes(pos)?'DEF':['MC','MCO','MCD'].includes(pos)?'MED':'ATA'}
function makeScenes(m){let role=v4Role(),pool=[...SCENES[role].map((x,i)=>({...x,v4id:`base-${role}-${i}`})),...V4_MATCH_POOL[role].map((x,i)=>({title:x[0],desc:x[1],opts:x[2].map(z=>[z[0],z[1],z[2],z[3],'']) ,v4id:`${role}-${i}`}))];if(m.enter<0){m.scenes=[];return}let memory=new Set((S.matchHistory||[]).slice(-37));let first=pool.filter(x=>!x.v4id||!memory.has(x.v4id));let all=first.length>=8?first:pool;let candidates=all.map((x,i)=>({x,key:Math.random(),i})).sort((a,b)=>a.key-b.key).map(x=>x.x);let total=m.enter===0?8:Math.min(5,Math.max(3,Math.floor((90-m.enter)/8)));let minutes=m.enter===0?[9,20,31,42,53,64,76,88]:Array.from({length:total},(_,i)=>Math.min(89,m.enter+3+Math.round((86-m.enter)*i/(Math.max(1,total-1)))));m.scenes=minutes.map((minute,i)=>({minute,scene:candidates[i%candidates.length],idx:i}));let used=m.scenes.filter(x=>x.scene.v4id).map(x=>x.scene.v4id);S.matchHistory.push(...used);S.matchHistory=S.matchHistory.slice(-90);m.weather=pick(V4_WX);m.matchStyle=pick(['Presión intensa','Bloque bajo','Juego directo','Posesión larga','Transiciones rápidas']);}
const _v4OldChance=chance;
chance=function(skill,diff,m){let val=_v4OldChance(skill,diff,m);if(m?.weather?.[0]==='Lluvia'&&['regate','tiro','pase'].includes(skill))val-=.035;if(m?.weather?.[0]==='Viento'&&['pase','tiro'].includes(skill))val-=.026;if(m?.weather?.[0]==='Calor'&&S.player.fitness<45)val-=.04;if(m?.minute>=74&&m.scoreUs<m.scoreThem&&['tiro','pase','regate'].includes(skill))val+=.025;return clamp(val,.07,.86)};
finishMatch=function(force=false){if(S?.match?.started&&!S.match.fastForward&&!force){S.match.pendingFinish=true;S.match.minute=90;persist();return}return _v4Original.finishMatch()};
function v4Choice(i){if(S?.match?.pendingFinish)return;let m=S?.match,step=m?.step||0;if(!m||!m.started)return;_v4Original.resolveChoice(i);if(S?.match===m){let minute=m.scenes[step]?.minute;let last=[...m.events].reverse().find(e=>e.minute===minute&&e.text.includes(' — '));if(last){m.lastFeedback=last.text;m.lastFeedbackMinute=minute}persist();render()}}
function v4Quick(){if(!S?.match)return;S.match.fastForward=true;try{_v4Original.quickMatch()}finally{if(S?.match)S.match.fastForward=false}}
function v4ConfirmFinish(){if(!S?.match?.pendingFinish)return;S.match.pendingFinish=false;finishMatch(true)}
function v4PlayMatch(){let out=_v4Original.playMatch();if(S?.match?.started&&S.match.enter===-1&&S.view==='match'){S.match.fastForward=true;finishMatch(true)}return out}
function v4NextWeek(){if(S.view!=='post')return;S.round++;let p=S.player,overhead=S.stage==='academy'?Math.min(25,p.wage*.28):p.wage<1600?Math.min(110,p.wage*.27):p.wage*.14;p.balance+=p.wage-overhead;p.fitness=clamp(p.fitness+rand(15,23)+(S.difficulty==='casual'?4:0));p.morale=clamp(p.morale+rand(-2,2));p.focus=clamp(p.focus+rand(-1,2));if(p.injured>0){p.injured--;if(!p.injured)note('Parte médico: recibes el alta competitiva.')}S.match=null;S.week={training:false,life:false};S.story=null;if(S.round>=S.schedule.length){seasonEnd();return}S.day=null;v4Init();v4EventFor(0);S.view='hub';activeTab='hub';persist();render()}
newSeasonSchedule=function(){_v4Original.newSeasonSchedule();S.day=null;v4Init();v4EventFor(0);persist()};
function v4Tag(t){return `<span class="v4-badge">${esc(t)}</span>`}
function v4Progress(){v4Init();return `<div class="v4-steps">${V4_DAYS.map((x,i)=>`<button class="v4-step ${S.day.index===i?'current':''} ${S.day.index>i?'done':''}" onclick="Game.openPhase(${i})" ${i>S.day.index?'disabled':''}><span class="v4-stepicon">${S.day.index>i?'✓':x.icon}</span><span><b>${x.name}</b><small>${x.date}</small></span></button>`).join('')}</div>`}
function v4EventCard(day){let kind=day===0?'training':'life',event=v4EventFor(day),done=S.day.answers[kind]!==undefined;return `<section class="v4-panel v4-event"><div class="v4-kicker">${day===0?'SITUACIÓN EN LA CIUDAD DEPORTIVA':'DECISIÓN FUERA DEL CAMPO'}</div><div class="v4-paneltitle"><h2>${esc(event.title)}</h2>${v4Tag(done?'Resuelta':'Nueva situación')}</div><p>${esc(event.text)}</p>${done?`<div class="v4-feedback">✓ ${S.day.answers[kind]<0?'Decidiste no intervenir.':esc(event.choices[S.day.answers[kind]][2])}</div>`:`<div class="v4-choices">${event.choices.map((o,i)=>`<button class="v4-option" onclick="Game.eventChoice('${kind}',${i})"><b>${esc(o[0])}</b><small>${effectsText(o[1])}</small></button>`).join('')}</div>`}</section>`}
function v4Training(){let p=S.player,isNow=S.day.index===0,done=S.week.training;return `<div class="v4-viewhead"><div><span class="v4-kicker">CENTRO DE ENTRENAMIENTO · J${S.round+1}</span><h1>Mejorar también es decidir.</h1><p>Elige la carga de esta semana y responde a lo que sucede en el grupo. El entrenamiento y el partido se juegan en días separados.</p></div>${v4Tag(isNow?'Día de entreno':'Jornada cerrada')}</div><div class="v4-compactmetrics"><div><small>Condición</small><b>${Math.round(p.fitness)}%</b></div><div><small>Confianza del míster</small><b>${Math.round(p.trust)}</b></div><div><small>Concentración</small><b>${Math.round(p.focus)}</b></div></div>${!isNow?`<div class="v4-panel"><h3>Sesión completada</h3><p>Este día ya se ha cerrado. Consulta tu siguiente actividad en Inicio.</p><button class="btn" onclick="Game.tab('hub')">Volver al calendario</button></div>`:`<div class="v4-mobiletoggle"><button class="${S.uiFocus!=='event'?'active':''}" onclick="Game.panel('plan')">Actividad</button><button class="${S.uiFocus==='event'?'active':''}" onclick="Game.panel('event')">Situación ${S.day.answers.training!==undefined||S.day.answers.life!==undefined?'✓':''}</button></div><div class="v4-traininggrid v4-focus-${S.uiFocus==='event'?'event':'plan'}"><section class="v4-panel"><div class="v4-paneltitle"><h2>Plan físico y técnico</h2>${v4Tag(done?'Completado':'Elige una sesión')}</div><div class="v4-drills">${TRAININGS.filter(x=>x.id!=='keeper'||p.pos==='POR').map(t=>`<button class="v4-drill" onclick="Game.train('${t.id}')" ${done?'disabled':''}><b>${esc(t.name)}</b><span>${t.fitness>=0?'+':'−'}${Math.abs(t.fitness)} físico</span><small>${esc(t.desc)}</small></button>`).join('')}</div></section>${v4EventCard(0)}</div><section class="v4-nextbar"><div><b>${done?'✓ Sesión realizada':'Sesión pendiente'} · ${S.day.answers.training!==undefined?'✓ Evento resuelto':'Evento pendiente'}</b><small>Tu forma física afecta a los partidos y a la posibilidad de lesionarte.</small></div><div class="actions"><button class="btn ghost" onclick="Game.dayNext(true)">Omitir pendientes</button><button class="btn" onclick="Game.dayNext(false)" ${!done||S.day.answers.training===undefined?'disabled':''}>Ir a vida personal →</button></div></section>`}`}
function v4LifeScreen(){let p=S.player,isNow=S.day.index===1,done=S.week.life;return `<div class="v4-viewhead"><div><span class="v4-kicker">VIDA PERSONAL · J${S.round+1}</span><h1>La carrera no termina al salir.</h1><p>Elige cómo pasar tus días libres. La moral, el descanso, las relaciones y el mercado también cuentan.</p></div>${v4Tag(isNow?'Vida y vestuario':'Jornada cerrada')}</div><div class="v4-compactmetrics"><div><small>Moral</small><b>${Math.round(p.morale)}</b></div><div><small>Química</small><b>${Math.round(p.chemistry)}</b></div><div><small>Saldo</small><b>${money(p.balance)}</b></div></div>${!isNow?`<div class="v4-panel"><h3>Fuera de este día</h3><p>Ya has avanzado a otro momento de la semana.</p><button class="btn" onclick="Game.tab('hub')">Volver al calendario</button></div>`:`<div class="v4-mobiletoggle"><button class="${S.uiFocus!=='event'?'active':''}" onclick="Game.panel('plan')">Actividad</button><button class="${S.uiFocus==='event'?'active':''}" onclick="Game.panel('event')">Situación ${S.day.answers.training!==undefined||S.day.answers.life!==undefined?'✓':''}</button></div><div class="v4-traininggrid v4-focus-${S.uiFocus==='event'?'event':'plan'}"><section class="v4-panel"><div class="v4-paneltitle"><h2>Tu tiempo libre</h2>${v4Tag(done?'Actividad elegida':'Una actividad')}</div><div class="v4-drills">${LIFE.map(t=>`<button class="v4-drill" onclick="Game.life('${t.id}')" ${done?'disabled':''}><b>${esc(t.name)}</b><span>${t.fitness>=0?'+':''}${t.fitness||0} físico</span><small>${esc(t.desc)}</small></button>`).join('')}</div></section>${v4EventCard(1)}</div><section class="v4-nextbar"><div><b>${done?'✓ Actividad realizada':'Actividad pendiente'} · ${S.day.answers.life!==undefined?'✓ Situación resuelta':'Situación pendiente'}</b><small>Después llega la convocatoria y el partido del fin de semana.</small></div><div class="actions"><button class="btn ghost" onclick="Game.dayNext(true)">Omitir pendientes</button><button class="btn" onclick="Game.dayNext(false)" ${!done||S.day.answers.life===undefined?'disabled':''}>Ir al día de partido →</button></div></section>`}`}
function v4Home(){v4Init();let p=S.player,u=upcoming(),r=avgRating(),s=S.stats,phase=V4_DAYS[S.day.index],youth=S.stage==='academy',thisEvent=S.day.index<2?v4EventFor(S.day.index):null;return `<div class="v4-viewhead v4-welcome"><div><div class="v4-kicker">TEMPORADA ${S.year}/${S.year+1} · JORNADA ${S.round+1}/${S.schedule.length}</div><h1>${esc(p.name)}<span class="v4-em">. Tu historia.</span></h1><p>${youth?`Cantera de ${esc(S.club.parent||S.club.name)} · ${esc(S.club.country)}`:`${esc(S.club.name)} · ${esc(leagueLabel())}`} · ${p.age} años · ${p.pos} · OVR ${overall(p)}.</p></div><span class="v4-ovr">${overall(p)}<small>MEDIA</small></span></div>${v4Progress()}<div class="v4-homegrid"><section class="v4-panel v4-feature"><div class="v4-kicker">AHORA · ${phase.date.toUpperCase()}</div><h2>${phase.icon} ${phase.name}</h2><p>${esc(phase.hint)}</p>${S.day.index===2?`<div class="v4-fixture"><span>${esc(S.club.name)}</span><b>VS</b><span>${esc(u?.opp||'—')}</span></div>`:`<div class="v4-nextsub">${thisEvent?`Situación: ${esc(thisEvent.title)}`:''}</div>`}<button class="btn" onclick="Game.openPhase(${S.day.index})">${S.day.index===2?'Ir al partido':'Continuar mi semana'} →</button></section><section class="v4-panel v4-numbers"><div class="v4-kicker">ESTA TEMPORADA</div><div class="v4-numbergrid"><div><b>${s.apps}</b><small>Partidos</small></div><div><b>${s.goals}</b><small>Goles</small></div><div><b>${s.assists}</b><small>Asist.</small></div><div><b>${r?r.toFixed(1):'—'}</b><small>Nota media</small></div></div><div class="v4-divider"></div><div class="v4-minirow"><span>Forma física</span><b>${Math.round(p.fitness)}%</b></div>${bar(p.fitness)}<div class="v4-minirow"><span>Confianza entrenador</span><b>${Math.round(p.trust)}/100</b></div>${bar(p.trust)}</section></div><div class="v4-shortcuts"><button onclick="Game.tab('player')"><strong>◎ Jugador</strong><small>Atributos y contrato</small></button><button onclick="Game.tab('agent')"><strong>♧ Representante</strong><small>Ofertas y objetivos</small></button><button onclick="Game.tab('league')"><strong>▥ Clasificación</strong><small>Resultados y calendario</small></button><button onclick="Game.tab('news')"><strong>◷ Noticias</strong><small>Tu historia reciente</small></button></div>${S.watchlist?.length?`<section class="v4-panel v4-scoutmin"><div class="v4-paneltitle"><h3>Un club sigue tus pasos</h3><button class="v4-textbtn" onclick="Game.tab('agent')">Todos los objetivos →</button></div><div class="v4-scoutrow"><b>${esc(S.watchlist[0].name)}</b>${v4Tag(Math.round(objectiveProgress(S.watchlist[0]).progress*100)+'% observado')}</div>${bar(objectiveProgress(S.watchlist[0]).progress*100)}</section>`:''}`}
function v4News(){return `<div class="v4-viewhead"><div><span class="v4-kicker">ARCHIVO PERSONAL</span><h1>Lo que ha pasado.</h1><p>Una cronología de tus decisiones y de cómo evoluciona tu carrera.</p></div></div><section class="v4-panel"><div class="v4-feed">${(S.inbox||[]).length?S.inbox.map(z=>`<div class="v4-feeditem"><span>T${S.seasonNo} · J${z.round}</span><p>${esc(z.text)}</p></div>`).join(''):'<p>Aquí aparecerán tus noticias.</p>'}</div></section>`}
function v4Settings(){return `<div class="v4-viewhead"><div><span class="v4-kicker">CONFIGURACIÓN</span><h1>Tu carrera, tus reglas.</h1><p>Guarda copias del progreso, importa partidas anteriores y controla tu simulación.</p></div></div><section class="v4-panel"><h2>Guardar y recuperar</h2><p>El guardado automático depende del navegador y del almacenamiento local. Por seguridad, exporta una copia de vez en cuando.</p><div class="actions"><button class="btn" onclick="Game.export()">↓ Exportar partida JSON</button><button class="btn secondary" onclick="document.getElementById('importFile').click()">↑ Importar partida</button></div><div class="v4-divider"></div><h3>Datos de tu partida</h3><div class="v4-minirow"><span>Simulación</span><b>${esc(S.difficulty==='casual'?'Casual':'Realista')}</b></div><div class="v4-minirow"><span>Eventos narrativos vistos</span><b>${S.eventHistory?.length||0}</b></div><div class="v4-minirow"><span>Situaciones de partido registradas</span><b>${S.matchHistory?.length||0}</b></div><div class="v4-divider"></div><button class="btn danger" onclick="Game.reset()">Empezar carrera nueva</button></section>`}
function v4MatchScreen(){let m=S.match,p=S.player,u=upcoming();if(!m){return `<div class="v4-viewhead"><div><span class="v4-kicker">FIN DE SEMANA · J${S.round+1}</span><h1>El día del partido.</h1><p>Convocatoria, instrucciones y decisiones sobre el césped. Prepararte bien importa.</p></div></div><section class="v4-panel"><div class="v4-kicker">${esc(leagueLabel())} · ${u?.home?'En casa':'A domicilio'}</div><div class="v4-bigfixture"><b>${esc(u?.home?S.club.name:u?.opp||'—')}</b><strong>VS</strong><b>${esc(u?.home?u?.opp||'—':S.club.name)}</b></div><div class="v4-compactmetrics"><div><small>Tu condición</small><b>${Math.round(p.fitness)}%</b></div><div><small>Tu confianza</small><b>${Math.round(p.trust)}</b></div><div><small>Rival (nivel)</small><b>${u?getClub(u.opp).power:'—'}</b></div></div><button class="btn" onclick="Game.startMatch()">Entrar en el vestuario →</button></section>`}
 let role=m.enter===0?'TITULAR':m.enter>0?'SUPLENTE':'NO CONVOCADO',scene=m.scenes[m.step],pending=m.pendingFinish,feedback=m.lastFeedback;
 return `<div class="v4-matchtop"><div><div class="v4-kicker">JORNADA ${S.round+1} · ${m.started?`MINUTO ${m.minute}'`:'TÚNEL DE VESTUARIOS'} · ${role}</div><h1>${m.started?'En directo.':'Últimas instrucciones.'}</h1></div>${v4Tag(m.weather?.[0]||'Partido')}</div><section class="v4-panel v4-scorepanel"><div class="v4-scoreteams"><b>${esc(m.home?S.club.name:m.opp)}</b><span>${m.home?m.scoreUs:m.scoreThem} : ${m.home?m.scoreThem:m.scoreUs}<small>${m.minute}' / 90'</small></span><b>${esc(m.home?m.opp:S.club.name)}</b></div><div class="v4-progressline"><span style="width:${Math.round(m.minute/90*100)}%"></span></div><div class="v4-matchmetrics"><div>Nota <b>${m.enter<0?'—':m.rating.toFixed(1)}</b></div><div>Goles <b>${m.stats.goals}</b></div><div>Asist. <b>${m.stats.assists}</b></div><div>Defensas <b>${p.pos==='POR'?m.stats.saves:m.stats.tackles}</b></div><div>Físico <b>${Math.round(p.fitness)}%</b></div></div></section>
 ${!m.started?`<section class="v4-panel"><div class="v4-paneltitle"><h2>${m.enter===0?'Sales de inicio':m.enter<0?'Te quedas sin minutos':`Entrarías sobre el ${m.enter}'`}</h2>${v4Tag(role)}</div><p>${m.enter<0?'Esta semana observarás desde el banquillo. Tu forma, confianza y rendimiento condicionan las convocatorias.':'El entrenador te pide que elijas cómo plantear tu actuación.'}</p><div class="v4-choices">${[['calm','Orden y control','Menos riesgo y desgaste'],['balance','Equilibrio','Alternar pausa y verticalidad'],['attack','Arriesgar y atacar','Más oportunidades y más exposición']].map(([v,n,desc])=>`<button class="v4-option ${m.tactics===v?'active':''}" onclick="Game.tactic('${v}')"><b>${n}</b><small>${desc}</small></button>`).join('')}</div><div class="actions" style="margin-top:18px"><button class="btn" onclick="Game.playMatch()">${m.enter===-1?'Ver resultado':'Salir al césped'} →</button><button class="btn secondary" onclick="Game.quick()">Simular encuentro</button></div></section>`:
 `<div class="v4-matchgrid"><div>${feedback?`<div class="v4-decisionfeedback"><span>ÚLTIMA ACCIÓN · ${m.lastFeedbackMinute}'</span><p>${esc(feedback)}</p></div>`:''}${pending?`<section class="v4-panel v4-last"><div class="v4-kicker">SILBATO FINAL · 90'</div><h2>Ya has terminado de jugar.</h2><p>La última decisión ha quedado registrada arriba. Puedes revisar el relato antes de cerrar el encuentro.</p><button class="btn" onclick="Game.confirmFinish()">Ver resultado y estadísticas →</button></section>`:scene?`<section class="v4-panel v4-action"><div class="v4-kicker">DECISIÓN ${m.step+1} / ${m.scenes.length} · MINUTO ${scene.minute}' · ${esc(m.matchStyle||'')}${m.weather?' · '+esc(m.weather[0]):''}</div><h2>${esc(scene.scene.title)}</h2><p>${esc(v4MatchContext(scene,m))}</p><div class="v4-choices">${scene.scene.opts.map(([title,skill,type,diff],i)=>`<button class="v4-option" onclick="Game.choice(${i})"><b>${esc(title)}</b><small>${diff>=.70?'Alto riesgo':diff>=.45?'Riesgo medio':'Más control'} · ${esc(ATTRS[skill]||'Concentración')}: ${Math.round(skill==='focus'?p.focus:p.attrs[skill]||50)}</small></button>`).join('')}</div></section>`:''}${!pending?`<button class="btn secondary" style="margin-top:12px" onclick="Game.quick()">Simular el resto del partido »</button>`:''}</div><section class="v4-panel v4-log"><div class="v4-paneltitle"><h3>Relato del partido</h3>${v4Tag(m.events.length+' acciones')}</div><div class="v4-matchfeed">${m.events.slice(-15).reverse().map(e=>`<div class="${e.highlight?'highlight':''}"><strong>${e.minute}'</strong><span>${esc(e.text)}</span></div>`).join('')}</div></section></div>`}`}
function v4Post(){return `<div class="v4-post">${postMatch()}</div>`}
const V4_NAV=[['hub','⌂','Inicio'],['training','◎','Entreno'],['life','◇','Vida'],['match','⚽','Partido'],['player','♙','Jugador'],['league','▥','Liga'],['agent','♧','Mercado'],['history','★','Carrera'],['news','◷','Noticias'],['settings','⚙','Ajustes']];
function v4Tab(tab){if(!S)return;if(S.view==='post'){notify('Termina la jornada desde el resumen del partido.');return}if(S.view==='match'&&S.match?.started){notify('Finaliza el partido para abrir el menú.');return}if(S.view==='season'){notify('Elige tu próximo club para empezar la nueva temporada.');return}S.view='hub';activeTab=tab;render();}
function render(){let root=$('root');if(!root)return;if(!S){root.innerHTML=`<div class="app v4-entry"><header class="v4-top"><div class="brand"><span class="brandicon">F</span><div><div class="brandname">FUERA DE GUIÓN</div><div class="eyebrow">Career mode · v5.0</div></div></div><div class="topright">${store.getItem(SAVE_KEY)?'<button class="tinybtn" onclick="Game.resume()">Continuar partida</button>':''}<button class="tinybtn" onclick="document.getElementById('importFile').click()">Importar</button></div></header>${setup()}<div class="footer">Simulación ficticia · Todo en un archivo · Sin internet</div></div>`;return}
 if(S.view==='draft'){root.innerHTML=`<div class="app v4-entry"><header class="v4-top"><div class="brand"><span class="brandicon">F</span><strong>FUERA DE GUIÓN</strong></div><button class="tinybtn" onclick="Game.reset()">Nueva carrera</button></header>${draftScreen()}</div>`;return}
 v4Init();let p=S.player,tab=S.view==='hub'?activeTab:S.view==='match'?'match':S.view==='post'?'match':S.view==='season'?'agent':'hub',center=S.view==='season'?seasonScreen():S.view==='post'?v4Post():S.view==='match'?v4MatchScreen():tab==='hub'?v4Home():tab==='training'?v4Training():tab==='life'?v4LifeScreen():tab==='match'?(S.day.index===2?v4MatchScreen():`<div class="v4-viewhead"><h1>El partido llegará.</h1><p>Antes toca preparar la semana. Completa entrenamiento y vida personal.</p></div><button class="btn" onclick="Game.tab('hub')">Ver calendario</button>`):tab==='player'?profile():tab==='league'?leagueView():tab==='agent'?agent():tab==='history'?history():tab==='news'?v4News():tab==='settings'?v4Settings():v4Home();
 let navHtml=V4_NAV.map(([id,ico,word])=>`<button class="v4-navbtn ${tab===id?'active':''}" onclick="Game.tab('${id}')"><span>${ico}</span><b>${word}</b></button>`).join('');root.innerHTML=`<div class="v4-shell"><aside class="v4-sidebar"><div class="v4-brand"><div class="brandicon">F</div><div><strong>FUERA DE GUIÓN</strong><small>CAREER MODE · 5.0</small></div></div><div class="v4-clubline"><span>${FLAGS[S.club.country]||'⚽'}</span><div><b>${esc(S.club.name)}</b><small>${esc(S.stage==='academy'?'Categoría Sub-19':leagueLabel())}</small></div></div><nav class="v4-nav">${navHtml}</nav><div class="v4-sidetail"><b>${esc(p.name)}</b><small>${p.pos} · ${overall(p)} OVR · ${Math.round(p.fitness)}% físico</small><div class="v4-divider"></div><span>Temporada ${S.seasonNo} · J${S.round+1}/${S.schedule.length}</span></div></aside><div class="v4-workspace"><header class="v4-toolbar"><div class="v4-mobbrand"><span class="brandicon">F</span><strong>FUERA DE GUIÓN</strong></div><span class="v4-breadcrumb">${esc(S.club.name)} <em>·</em> ${S.year}/${S.year+1}</span><div class="v4-tools"><span class="v4-level">${overall(p)} OVR</span><button onclick="Game.tab('settings')" aria-label="Ajustes" title="Ajustes">⚙</button></div></header><main class="v4-main">${center}</main><footer class="v4-footer">SIMULACIÓN DE CARRERA · DATOS FICTICIOS · GUARDADO ${STORE_OK?'AUTOMÁTICO':'NO DISPONIBLE'}</footer></div><nav class="v4-bottomnav">${V4_NAV.filter(x=>['hub','training','life','match','agent','settings'].includes(x[0])).map(([id,ico,word])=>`<button class="${tab===id?'active':''}" onclick="Game.tab('${id}')"><span>${ico}</span><small>${word}</small></button>`).join('')}</nav></div>`;}
Object.assign(window.Game,{tab:v4Tab,train:v4Train,life:v4Life,choice:v4Choice,quick:v4Quick,confirmFinish:v4ConfirmFinish,playMatch:v4PlayMatch,next:v4NextWeek,openPhase:v4OpenPhase,eventChoice:v4EventChoice,dayNext:v4DayNext,panel:v4Panel,back:v4BackHome});

$('importFile').addEventListener('change',importGame);
if(!store.getItem(SAVE_KEY)&&store.getItem('fuera_de_guion_carrera_v3')){try{let old=JSON.parse(store.getItem('fuera_de_guion_carrera_v3'));if(old?.player&&old.version===3)store.setItem(SAVE_KEY,JSON.stringify(old))}catch(e){}}
if(store.getItem(SAVE_KEY)){resume()}else render();